window.TG_BUKU = [{"no": 1, "judul": "Pengantar Ilmu Sejarah, Hindu-Buddha dan Islam", "pendek": "Pengantar Ilmu Sejarah, Hindu-Buddha dan Islam", "periode": "Hindu-Buddha dan Islam", "warna": "#5B1A1A"}, {"no": 2, "judul": "Jejak Kolonialisme dan Perlawanan Nusantara", "pendek": "Jejak Kolonialisme dan Perlawanan", "periode": "Abad ke-15 sampai ke-19", "warna": "#14304F"}, {"no": 3, "judul": "Dari Kesadaran Nasional Menuju Indonesia Merdeka", "pendek": "Kesadaran Nasional Menuju Merdeka", "periode": "1900 sampai 1945", "warna": "#1F4D3A"}, {"no": 4, "judul": "Dari Revolusi Kemerdekaan Menuju Demokrasi Terpimpin", "pendek": "Revolusi Menuju Demokrasi Terpimpin", "periode": "1945 sampai 1965", "warna": "#6A3B12"}, {"no": 5, "judul": "Dari Orde Baru Menuju Indonesia Reformasi", "pendek": "Orde Baru Menuju Reformasi", "periode": "1966 sampai era Reformasi", "warna": "#3A2A55"}];
window.TG_SOAL = {"1":[{"no":1,"tipe":"PG","judul":"Sejarah sebagai ilmu","stimulus":"Sebuah museum menampilkan berita koran lama, foto kegiatan pasar, dan catatan wawancara. Seorang peneliti memeriksa kapan tiap sumber dibuat, siapa pembuatnya, serta membandingkan isi sumber-sumber tersebut sebelum menulis kisah perkembangan pasar.","tanya":"Tindakan manakah yang paling menunjukkan bahwa sejarah dipelajari sebagai ilmu?","analisis":["Tidak tepat. Kisah yang menarik belum tentu dapat dipertanggungjawabkan bila tanpa bukti.","Tidak tepat. Kesaksian lisan tetap perlu diperiksa konteks dan kesesuaiannya dengan sumber lain.","Tepat. Pemeriksaan asal, waktu, dan isi sumber membantu menyusun penjelasan berdasarkan bukti.","Tidak tepat. Memilih bukti yang sejalan saja membuat kesimpulan menjadi berat sebelah.","Tidak tepat. Tampilan fisik tidak otomatis menunjukkan usia atau keandalan suatu sumber."],"strategi":["Tanyakan: apakah peneliti menguji bukti atau hanya bercerita?","Cari tindakan seperti memeriksa sumber, membandingkan informasi, dan menarik kesimpulan.","Singkirkan jawaban yang mengandalkan tebakan, imajinasi, atau satu sumber saja."],"rujukan":{"label":"Kerangka TKA Sejarah - Pusmendik","url":"https://pusmendik.kemendikdasmen.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"opsi":["Menulis kisah yang menarik walau tidak didukung sumber.","Menganggap semua kisah lisan pasti sama akuratnya.","Memeriksa sumber secara sistematis sebelum menyusun penjelasan.","Memilih hanya sumber yang mendukung pendapat awal peneliti.","Mengurutkan semua sumber berdasarkan tampilannya yang paling tua."],"kunci":["C"]},{"no":2,"tipe":"BS","judul":"Sebab-akibat dan perubahan","stimulus":"Ilustrasi: Sebuah kampung tepi sungai dahulu mengirim hasil kebun menggunakan perahu. Setelah jalan darat dibangun, sebagian hasil kebun dikirim memakai mobil. Namun, warga di beberapa dusun masih memakai perahu untuk mencapai pasar ketika jalan sulit dilalui.","tanya":"Tentukan Benar atau Salah pada setiap pernyataan berdasarkan bacaan.","analisis":["Benar. Perubahan sarana angkut dikaitkan dengan hadirnya jalan darat.","Salah. Bacaan justru menyebutkan sebagian warga masih memakai perahu; kata \"semua\" membuat klaim keliru.","Benar. Kebiasaan lama tetap bertahan berdampingan dengan cara baru."],"strategi":["Temukan informasi \"sebelum\" dan \"sesudah\" peristiwa.","Pisahkan perubahan (yang berbeda) dan keberlanjutan (yang masih bertahan).","Waspadai kata mutlak seperti \"seluruh\", \"selalu\", dan \"tidak pernah\"."],"rujukan":{"label":"Kerangka TKA Sejarah - Pusmendik","url":"https://pusmendik.kemendikdasmen.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"pernyataan":["Pembangunan jalan menjadi salah satu faktor perubahan cara mengangkut hasil kebun.","Karena mobil mulai digunakan, dapat disimpulkan semua transportasi sungai langsung hilang.","Penggunaan perahu oleh sebagian warga menunjukkan adanya keberlanjutan."],"kunci":["B","S","B"],"label":"benar"},{"no":3,"tipe":"PG","judul":"Masa lalu dan masa kini","stimulus":"Di suatu kota, pasar utama sejak lama berada dekat muara sungai. Pada masa lalu pedagang datang melalui jalur air. Kini sebagian besar barang dikirim lewat jalan raya, tetapi pasar masih menjadi tempat pertemuan pedagang dari berbagai daerah.","tanya":"Kesimpulan yang paling tepat tentang hubungan masa lalu dan masa kini adalah ...","analisis":["Tidak tepat. Posisi pasar tetap membantu menjelaskan perkembangan kota.","Tidak tepat. Moda pengangkutan mengalami perubahan yang jelas.","Tidak tepat. Perdagangan justru tetap berlangsung.","Tepat. Pernyataan ini memadukan unsur keberlanjutan dan perubahan.","Tidak tepat. Informasi tentang profesi seluruh penduduk tidak tersedia."],"strategi":["Cari dua hal: apa yang tetap dan apa yang berubah.","Pilih kesimpulan yang mencakup keduanya tanpa menambah fakta baru.","Jangan menyimpulkan \"semua warga\" bila sumber hanya membahas pasar."],"rujukan":{"label":"Kerangka TKA Sejarah - Pusmendik","url":"https://pusmendik.kemendikdasmen.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"opsi":["Letak pasar tidak lagi berhubungan dengan sejarah kota.","Semua kegiatan ekonomi pasar dari masa lalu bertahan tanpa perubahan.","Perubahan kendaraan membuktikan kegiatan perdagangan sudah berhenti.","Fungsi pasar sebagai tempat perdagangan berlanjut, sedangkan jalur angkutnya berubah.","Keberadaan sungai memastikan seluruh penduduk kota berprofesi sebagai pedagang."],"kunci":["D"]},{"no":4,"tipe":"MC","judul":"Perubahan tradisi masyarakat","stimulus":"Catatan pengamatan sebuah festival desa (ilustrasi pembelajaran): pada 1995, undangan disampaikan dari rumah ke rumah, pertunjukan dipentaskan di lapangan, dan hasil kerajinan dijual langsung. Pada 2025, undangan disebar melalui media sosial; pertunjukan tetap diadakan di lapangan dan disiarkan langsung; sebagian kerajinan juga dijual daring.","tanya":"Pernyataan manakah yang sesuai dengan konsep perubahan dan keberlanjutan? Pilih semua jawaban yang benar.","analisis":["Tepat. Penyebaran undangan beralih dari kunjungan langsung menjadi media sosial.","Tidak tepat. Pertunjukan di lapangan justru masih dilaksanakan.","Tepat. Kegiatan seninya berlanjut, sementara siaran langsung merupakan perubahan cara menjangkau penonton.","Tidak tepat. Bacaan memakai kata \"sebagian\" dijual daring, bukan semuanya.","Tepat. Penjualan kerajinan tetap ada dengan tambahan pilihan daring."],"strategi":["Pada PGK, periksa A sampai E satu per satu; jangan berhenti setelah menemukan dua jawaban.","Pasangkan setiap opsi dengan kalimat pendukung dari bacaan.","Ingat: munculnya cara baru tidak otomatis menghapus cara lama."],"rujukan":{"label":"Kerangka TKA Sejarah - Pusmendik","url":"https://pusmendik.kemendikdasmen.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"opsi":["Cara menyebarkan informasi festival telah mengalami perubahan.","Pertunjukan di lapangan sudah sepenuhnya hilang.","Kegiatan seni masih dilaksanakan meskipun sarana penyajiannya bertambah.","Penjualan daring membuktikan tidak ada lagi pembelian langsung.","Perdagangan kerajinan berlanjut dengan tambahan saluran penjualan."],"kunci":["A","C","E"]},{"no":5,"tipe":"MC","judul":"Sumber primer dan sekunder","stimulus":"Seorang siswa meneliti banjir besar yang terjadi pada 1930. Ia menemukan sejumlah bahan: surat seorang petugas bertanggal 1930, buku sejarah terbit 2018, foto lokasi yang diambil saat banjir, kisah seorang cucu yang hanya mendengar cerita dari kakeknya, serta laporan koran terbit sehari setelah kejadian.","tanya":"Bahan manakah yang dapat digunakan sebagai sumber primer mengenai kejadian tahun 1930 itu? Pilih semua jawaban yang benar.","analisis":["Tepat. Surat sezaman adalah rekaman langsung dari masa peristiwa.","Tidak tepat. Buku tersebut merupakan kajian yang dibuat jauh setelah kejadian.","Tepat. Foto sezaman merekam keadaan ketika peristiwa berlangsung.","Tidak tepat untuk kategori ini. Cucu hanya menyampaikan cerita orang lain, bukan kesaksian langsung.","Tepat. Berita sezaman dapat menjadi sumber primer; isinya tetap perlu diperiksa."],"strategi":["Cari dua petunjuk: kapan sumber dibuat dan seberapa langsung hubungannya dengan peristiwa.","Jangan mengira semua bahan yang tua pasti akurat; sumber primer juga perlu diuji.","Bedakan saksi langsung dengan orang yang hanya mengulang cerita."],"rujukan":{"label":"Kerangka TKA Sejarah - Pusmendik","url":"https://pusmendik.kemendikdasmen.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"opsi":["Surat petugas yang ditulis pada 1930.","Buku sejarah terbitan 2018 yang membahas banjir tersebut.","Foto yang diambil di lokasi ketika banjir terjadi.","Cerita cucu pada 2025 yang tidak menyaksikan langsung banjir.","Koran yang memberitakan peristiwa sehari setelah kejadian."],"kunci":["A","C","E"]},{"no":6,"tipe":"BS","judul":"Memeriksa perbedaan sumber","stimulus":"Dua sumber menceritakan sebuah rapat desa. Notula rapat yang dibuat pada hari kejadian menyebut 35 peserta hadir. Seorang penulis buku beberapa puluh tahun kemudian menyebut \"sekitar 50 orang\" tanpa menjelaskan dari mana angka itu diperoleh. Siswa hendak menulis laporan mengenai jumlah peserta rapat.","tanya":"Tentukan Benar atau Salah pada setiap langkah penelitian berikut.","analisis":["Benar. Asal angka perlu diteliti karena dua sumber memberikan informasi berbeda.","Salah. Waktu penerbitan saja tidak memastikan kebenaran; sumber sezaman pun tetap perlu diuji.","Benar. Menjelaskan perbedaan dan alasan pemilihan bukti menunjukkan sikap kritis."],"strategi":["Saat sumber berbeda, jangan terburu-buru memilih yang paling terkenal atau paling baru.","Periksa pembuat, waktu, tujuan, dan cara memperoleh informasinya.","Jika buktinya belum cukup, tuliskan keterbatasannya dengan jujur."],"rujukan":{"label":"Kerangka TKA Sejarah - Pusmendik","url":"https://pusmendik.kemendikdasmen.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"pernyataan":["Siswa perlu menelusuri asal angka dari kedua sumber sebelum menulis jumlah peserta.","Karena dibuat belakangan, buku tersebut pasti benar dan notula pasti salah.","Siswa dapat menulis bahwa ada perbedaan angka dan menjelaskan bukti yang mendukung pilihannya."],"kunci":["B","S","B"],"label":"benar"},{"no":7,"tipe":"MC","judul":"Menilai teori masuknya pengaruh India","stimulus":"Di wilayah pesisir Nusantara ditemukan benda dagangan dari India. Di tempat lain terdapat prasasti berbahasa Sanskerta dan tinggalan keagamaan Hindu-Buddha. Temuan-temuan tersebut menunjukkan adanya hubungan budaya, tetapi tidak dengan sendirinya menjelaskan hanya satu jalan penyebarannya.","tanya":"Kesimpulan manakah yang dapat dipertanggungjawabkan dari bukti tersebut? Pilih semua jawaban yang benar.","analisis":["Tepat. Barang dagangan mendukung adanya jaringan hubungan antarmasyarakat.","Tidak tepat. Temuan yang ada tidak membuktikan hanya satu kelompok sebagai pembawa pengaruh.","Tidak tepat. Perubahan keyakinan dan kebudayaan tidak terjadi seragam di semua tempat.","Tepat. Masyarakat penerima bukan pihak pasif; pengaruh luar dapat diolah sesuai kondisi lokal.","Tepat. Dalam sejarah, teori harus diuji menggunakan beberapa jenis bukti."],"strategi":["Bedakan \"bukti adanya kontak\" dengan \"bukti cara penyebaran\".","Waspadai opsi yang memakai kata \"hanya\", \"semua\", atau \"pasti\" tanpa dukungan.","Pilih pernyataan yang sebanding dengan kekuatan bukti yang tersedia."],"rujukan":{"label":"BPK Wilayah V - Pengaruh Budaya Hindu dan Buddha","url":"https://kebudayaan.kemdikbud.go.id/bpcbjambi/pengaruh-budaya-ada-hindu-dan-juga-buddha/","umum":false},"opsi":["Hubungan perdagangan dapat menjadi salah satu jalur pertemuan budaya.","Semua pengaruh Hindu-Buddha pasti dibawa hanya oleh satu kelompok pendatang.","Semua masyarakat Nusantara langsung menganut agama yang sama pada waktu bersamaan.","Kelompok masyarakat setempat mungkin ikut memilih dan mengolah pengaruh budaya yang datang.","Teori penyebaran perlu dinilai dengan membandingkan bukti, bukan menganggap satu dugaan pasti benar."],"kunci":["A","D","E"]},{"no":8,"tipe":"PG","judul":"Kutai dan prasasti Yupa","stimulus":"Salah satu prasasti Yupa dari Muara Kaman menyebut nama Kudungga, Aswawarman, dan Mulawarman. Prasasti lainnya mencatat pemberian persembahan oleh Mulawarman. Prasasti tersebut ditulis dengan aksara Pallawa dan bahasa Sanskerta.","tanya":"Informasi apa yang paling kuat didukung oleh keterangan prasasti Yupa?","analisis":["Tidak tepat. Prasasti tidak menyatakan Kutai berada di bawah pemerintahan langsung India.","Tepat. Silsilah raja dan persembahan keagamaan tercatat dalam Yupa.","Tidak tepat. Bahasa prasasti tidak menggambarkan kemampuan baca seluruh penduduk.","Tidak tepat. Prasasti tidak menyajikan daftar lengkap kegiatan ekonomi.","Tidak tepat. Kutai jauh lebih awal daripada masa kerajaan Islam di Jawa."],"strategi":["Perhatikan apa yang benar-benar tertulis dalam prasasti.","Bedakan data sumber (nama raja, pemberian) dari dugaan yang terlalu luas (semua warga).","Jangan terpancing pilihan yang menyebut informasi di luar bukti."],"rujukan":{"label":"BPCB Kalimantan Timur - Situs Muara Kaman","url":"https://kebudayaan.kemdikbud.go.id/bpcbkaltim/peran-pusat-dan-daerah-dalam-pengelolaan-situs-cagar-budaya-studi-kasus-situs-muara-kaman-di-kutai-kartanegara-provinsi-kalimantan-timur/","umum":false},"opsi":["Kutai diperintah langsung oleh penguasa India yang tinggal di Nusantara.","Ada silsilah penguasa dan kegiatan keagamaan yang melibatkan raja serta brahmana.","Semua masyarakat Kutai sudah dapat membaca bahasa Sanskerta.","Perdagangan adalah satu-satunya kegiatan ekonomi penduduk Kutai.","Kerajaan Kutai berdiri setelah seluruh kerajaan Islam di Jawa."],"kunci":["B"]},{"no":9,"tipe":"BS","judul":"Tarumanagara dan pengelolaan air","stimulus":"Prasasti Tugu dari masa Raja Purnawarman menyebut penggalian saluran yang berhubungan dengan Gomati dan Candrabhaga. Prasasti ini menjadi petunjuk bahwa penguasa Tarumanagara memberi perhatian pada pekerjaan pengelolaan air.","tanya":"Tentukan Benar atau Salah pada setiap kesimpulan berikut.","analisis":["Benar. Isi prasasti secara langsung berkaitan dengan pekerjaan saluran air.","Salah. Tidak ada informasi tentang pekerjaan seluruh penduduk pada prasasti.","Benar. Pekerjaan pembangunan saluran air menunjukkan kegiatan pengorganisasian; rincian pelaksananya tetap perlu sumber tambahan."],"strategi":["Pisahkan apa yang disebut sumber dan apa yang bisa disimpulkan secara wajar.","Jika soal memakai \"semua penduduk\", periksa apakah data memang mencakup semuanya.","Jangan menganggap satu prasasti dapat menjelaskan seluruh kehidupan kerajaan."],"rujukan":{"label":"Direktorat Pelindungan Kebudayaan - Tarumanagara (topik terkait)","url":"https://kebudayaan.kemdikbud.go.id/dpk/dari-kerajaan-kendan-kemudian-galuh-barulah-sunda/","umum":false},"pernyataan":["Prasasti Tugu dapat digunakan untuk mengkaji kebijakan pengelolaan air pada masa Tarumanagara.","Prasasti Tugu memastikan semua penduduk Tarumanagara memiliki pekerjaan yang sama.","Pekerjaan saluran air menunjukkan adanya kemampuan mengerahkan tenaga untuk proyek berskala besar."],"kunci":["B","S","B"],"label":"benar"},{"no":10,"tipe":"PG","judul":"Sriwijaya sebagai simpul kawasan","stimulus":"Catatan perjalanan I-Tsing (Yijing) menggambarkan Sriwijaya sebagai tempat belajar agama Buddha sebelum melanjutkan studi ke India. Sementara itu, posisi kerajaan di jalur pelayaran Asia mendukung hubungan niaga dengan banyak kawasan.","tanya":"Gabungan kedua informasi tersebut paling tepat menunjukkan Sriwijaya sebagai ...","analisis":["Tidak tepat. Stimulus menekankan pelayaran, perdagangan, dan pendidikan.","Tepat. Peran ekonomi maritim dan pusat belajar terlihat dari dua informasi.","Tidak tepat. Catatan perjalanan justru memperlihatkan hubungan antarwilayah.","Tidak tepat. I-Tsing memberikan keterangan tentang kegiatan belajar Buddha.","Tidak tepat. Sumber tidak menyatakan semua pengetahuan berasal dari satu kota."],"strategi":["Satukan informasi dari kedua sumber, jangan memilih berdasarkan satu kalimat saja.","Cari opsi yang mencakup seluruh petunjuk penting: dagang + pendidikan.","Singkirkan pilihan yang bertentangan langsung dengan stimulus."],"rujukan":{"label":"BPK Wilayah V - Sriwijaya dan Nalanda","url":"https://kebudayaan.kemdikbud.go.id/bpkw5/sriwijaya-dan-nalanda-hubungan-damai-dijembatani-agama/","umum":false},"opsi":["Kerajaan yang hanya memusatkan perhatian pada pertanian pedalaman.","Pusat hubungan perdagangan dan pembelajaran agama Buddha di kawasan maritim.","Wilayah yang menutup diri dari perjalanan sarjana dan pedagang asing.","Pelabuhan yang tidak memiliki kegiatan keagamaan.","Kerajaan yang seluruh pengetahuannya berasal dari satu kota di India."],"kunci":["B"]},{"no":11,"tipe":"BS","judul":"Mataram Kuno dan candi","stimulus":"Di Jawa Tengah berkembang bangunan keagamaan besar pada masa Mataram Kuno. Borobudur dikenal sebagai peninggalan Buddha, sedangkan Prambanan adalah kompleks candi Hindu. Keduanya menjadi sumber untuk mempelajari perkembangan seni dan keagamaan masa itu.","tanya":"Tentukan Benar atau Salah pada pernyataan berikut.","analisis":["Benar. Borobudur memuat unsur penting agama Buddha dalam bangunan dan reliefnya.","Benar. Prambanan dikaitkan dengan tradisi Hindu, khususnya pemujaan Trimurti.","Salah. Kedua kompleks menunjukkan keberadaan tradisi keagamaan yang berbeda."],"strategi":["Cocokkan setiap candi dengan bukti bentuk dan tradisi keagamaannya.","Jangan menyimpulkan satu agama saja dari dua contoh yang berbeda.","Gunakan kata kunci \"Borobudur-Buddha\" dan \"Prambanan-Hindu\" sebagai titik awal."],"rujukan":{"label":"BPK Wilayah V - Masa Hindu Buddha di Sumatera (topik terkait)","url":"https://kebudayaan.kemdikbud.go.id/bpkw5/masa-hindu-buddha-di-sumatera/","umum":false},"pernyataan":["Borobudur dapat digunakan untuk mengkaji seni bangunan dan keyakinan Buddha.","Prambanan terutama dikenal sebagai kompleks keagamaan bercorak Hindu.","Borobudur dan Prambanan adalah bukti bahwa di Mataram Kuno hanya berkembang satu agama."],"kunci":["B","B","S"],"label":"benar"},{"no":12,"tipe":"MC","judul":"Menafsirkan jangkauan Majapahit","stimulus":"Teks sastra Nagarakretagama memuat sejumlah nama daerah yang berhubungan dengan Majapahit. Para peneliti mengingatkan bahwa penyebutan nama daerah dalam sastra istana tidak selalu berarti seluruh wilayah dikelola langsung dengan bentuk pemerintahan yang sama.","tanya":"Sikap paling tepat dalam menafsirkan jangkauan Majapahit adalah ... (pilih semua yang benar).","analisis":["Tepat. Hubungan politik di masa lalu dapat bermacam-macam, tidak selalu pemerintahan langsung.","Tidak tepat. Konsep provinsi negara modern tidak bisa langsung diterapkan pada abad ke-14.","Tepat. Pemeriksaan silang membuat penafsiran lebih kuat.","Tidak tepat. Karya sastra tetap bernilai sebagai sumber jika dibaca secara kritis.","Tepat. Teks istana dapat memiliki tujuan pujian politik yang perlu dipertimbangkan."],"strategi":["Tanyakan apa arti \"berhubungan\" atau \"dikuasai\" dalam konteks masanya.","Hindari menyamakan kerajaan masa lalu dengan peta negara modern.","Bandingkan beberapa sumber, terutama untuk klaim wilayah yang sangat luas."],"rujukan":{"label":"BPK Wilayah V - Perjalanan Hidup Bangsa Bahari (topik terkait)","url":"https://kebudayaan.kemdikbud.go.id/bpcbjambi/perjalanan-hidup-bangsa-bahari/","umum":false},"opsi":["Membedakan daerah yang dikelola langsung dengan daerah yang mempunyai hubungan pengaruh atau upeti.","Menganggap semua nama daerah di dalam teks otomatis menjadi provinsi seperti Indonesia modern.","Membandingkan berita sastra istana dengan prasasti, tinggalan arkeologis, dan sumber lain.","Menolak semua isi Nagarakretagama karena karya sastra tidak pernah berguna untuk sejarah.","Mempertimbangkan tujuan penulisan teks istana ketika menilai klaim tentang kekuasaan."],"kunci":["A","C","E"]},{"no":13,"tipe":"PG","judul":"Warisan budaya dan perubahan fungsi","stimulus":"Candi-candi peninggalan Hindu-Buddha yang dahulu menjadi tempat kegiatan keagamaan kini juga dirawat sebagai cagar budaya, tempat belajar, dan tujuan kunjungan. Beberapa unsur seni, cerita, atau bentuk bangunannya tetap dikenali oleh masyarakat.","tanya":"Kesimpulan paling tepat dari bacaan tersebut adalah ...","analisis":["Tidak tepat. Fungsi pendidikan dan kunjungan kini dapat berbeda dari fungsi dahulu.","Tidak tepat. Nilai sejarah tetap penting meskipun kerajaan sudah tidak ada.","Tepat. Pelestarian dapat berjalan bersama perubahan penggunaan dan pemaknaan.","Tidak tepat. Bacaan tidak membuktikan seluruh tradisi hilang.","Tidak tepat. Justru peninggalan budaya dapat menjadi sumber belajar sejarah."],"strategi":["Temukan contoh perubahan fungsi dan unsur yang masih bertahan.","Pilih jawaban yang tidak menghapus keragaman makna warisan budaya.","Jangan terkecoh kata \"seluruh\" atau \"hanya\" bila sumber lebih terbatas."],"rujukan":{"label":"Kemdikbud - Mengenal Candi Borobudur sebagai Warisan Dunia","url":"https://kebudayaan.kemdikbud.go.id/ditwdb/mengenal-candi-borobudur-sebagai-warisan-dunia/","umum":false},"opsi":["Seluruh fungsi candi pada masa lalu dan sekarang selalu sama.","Cagar budaya hanya bernilai jika masih dipakai untuk kegiatan kerajaan.","Warisan budaya dapat tetap terpelihara meskipun cara pemanfaatannya berkembang.","Adanya wisata sejarah membuktikan seluruh tradisi Hindu-Buddha sudah hilang.","Peninggalan budaya tidak dapat menjadi sumber untuk belajar kehidupan masa lalu."],"kunci":["C"]},{"no":14,"tipe":"PG","judul":"Membaca bukti awal perkembangan Islam","stimulus":"Peneliti menemukan nisan Fatimah binti Maimun di Leran, Gresik, dengan angka tahun 1082 M. Di Aceh, nisan Sultan Malik as-Salih bertahun 1297 M menjadi sumber penting bagi sejarah Samudra Pasai. Kedua temuan berasal dari tempat dan masa yang berbeda.","tanya":"Kesimpulan yang paling aman berdasarkan dua temuan tersebut adalah ...","analisis":["Tidak tepat. Bukti Gresik berangka lebih awal daripada 1297 M.","Tidak tepat. Satu nisan tidak membuktikan agama seluruh penduduk Nusantara.","Tidak tepat. Riwayat setiap kesultanan perlu diteliti dengan bukti setempat.","Tepat. Kedua nisan menunjukkan jejak Islam pada lokasi dan masa berbeda.","Tidak tepat. Menentukan rute dan proses kedatangan memerlukan beragam sumber lain."],"strategi":["Bedakan \"bukti sudah ada\" dengan \"bukti pertama kali datang\".","Bandingkan tanggal dan wilayah tanpa menyimpulkan nasib seluruh Nusantara.","Jauhi jawaban yang menyatakan satu bukti menyelesaikan seluruh perdebatan."],"rujukan":{"label":"BPK Wilayah XI - Proses Masuknya Islam ke Jawa Timur","url":"https://kebudayaan.kemdikbud.go.id/bpkw11/proses-masuknya-islam-ke-jawa-timur/","umum":false},"opsi":["Islam baru dikenal di Nusantara setelah tahun 1297 M.","Seluruh masyarakat Nusantara memeluk Islam sejak tahun 1082 M.","Nisan Malik as-Salih membuktikan seluruh kerajaan Islam memiliki asal-usul yang sama.","Terdapat bukti perkembangan komunitas atau penguasa Muslim di tempat dan masa berbeda.","Tahun pada satu nisan cukup untuk memastikan satu-satunya rute kedatangan Islam."],"kunci":["D"]},{"no":15,"tipe":"PG","judul":"Samudra Pasai dan jaringan niaga","stimulus":"Samudra Pasai berada di jalur pelayaran yang menghubungkan berbagai pusat perdagangan. Sumber-sumber tentang kesultanan ini, termasuk nisan penguasa dan catatan perjalanan, menunjukkan hubungan antara perkembangan pusat kekuasaan Islam dan kegiatan niaga di pesisir Sumatra.","tanya":"Hubungan yang paling masuk akal dari keterangan tersebut adalah ...","analisis":["Tepat. Jalur niaga menjadi ruang pertemuan ekonomi, sosial, dan budaya.","Tidak tepat. Perdagangan justru membuka berbagai perubahan dan pertukaran.","Tidak tepat. Stimulus menekankan posisi maritim Samudra Pasai.","Tidak tepat. Proses perkembangan Islam berbeda-beda di berbagai wilayah.","Tidak tepat. Kepentingan pelaku perdagangan tidak harus sama."],"strategi":["Temukan kata kunci \"pelabuhan\", \"jaringan\", dan \"pusat kekuasaan\".","Cari pilihan yang menjelaskan hubungan beberapa bidang sekaligus.","Hindari kesimpulan seragam bagi wilayah yang sangat luas."],"rujukan":{"label":"Direktorat Pelindungan Kebudayaan - Makam Samudra Pasai","url":"https://kebudayaan.kemdikbud.go.id/dpk/kompleks-makam-kuno-leubok-tuwe-makam-syuhada-awal-samudra-pasai/","umum":false},"opsi":["Jalur niaga dapat mempertemukan pedagang, gagasan agama, dan kepentingan kekuasaan.","Perdagangan membuat masyarakat pesisir tidak pernah mengalami perubahan budaya.","Kesultanan hanya bergantung pada hasil pertanian pedalaman yang tidak berhubungan dengan laut.","Islamisasi seluruh Nusantara dilakukan serentak dari satu pelabuhan.","Para pedagang selalu memiliki kepentingan politik yang identik."],"kunci":["A"]},{"no":16,"tipe":"BS","judul":"Demak dan perubahan politik-budaya","stimulus":"Kesultanan Demak tumbuh sebagai salah satu pusat Islam di pesisir utara Jawa. Masjid Agung Demak dan kisah keterlibatan para wali menjadi bagian dari warisan sejarahnya. Peralihan politik pada masa itu berlangsung dalam masyarakat yang masih memiliki berbagai tradisi budaya lebih tua.","tanya":"Tentukan Benar atau Salah pada setiap pernyataan berikut.","analisis":["Benar. Bangunan keagamaan serta aktivitas para wali merupakan petunjuk historis penting.","Salah. Perubahan budaya biasanya berlangsung bertahap dan tidak seragam.","Benar. Sebagian unsur baru berkembang sementara unsur lama tetap hidup dan berubah bentuk."],"strategi":["Pisahkan perubahan kerajaan/penguasa dari perubahan budaya penduduk.","Jangan menganggap pergantian kekuasaan selalu menghapus kebiasaan lama seketika.","Coba cari bukti peninggalan fisik dan tradisi yang masih berlangsung."],"rujukan":{"label":"Direktorat Pelindungan Kebudayaan - Masjid Sunan Muria (topik terkait)","url":"https://kebudayaan.kemdikbud.go.id/dpk/masjid-sunan-muria-kesederhanaan-kecintaan-pada-alam-dan-kepedulian-pada-sesama/","umum":false},"pernyataan":["Masjid dan kegiatan para wali dapat menjadi petunjuk perkembangan kehidupan Islam di Demak.","Berdirinya kesultanan Islam berarti semua tradisi masyarakat Jawa yang lebih tua langsung lenyap.","Perubahan politik dan keberlanjutan unsur budaya dapat terjadi pada masa yang sama."],"kunci":["B","S","B"],"label":"benar"},{"no":17,"tipe":"MC","judul":"Aceh, Banten, dan perdagangan lada","stimulus":"Setelah Portugis menguasai Malaka pada 1511, kegiatan niaga di Asia Tenggara tidak berhenti, tetapi sebagian jalurnya bergeser. Aceh dan Banten berkembang sebagai pusat perdagangan penting. Di Banten, meningkatnya permintaan lada mendorong perluasan penanaman komoditas tersebut dan memengaruhi kehidupan penduduk.","tanya":"Dampak yang sesuai dengan bacaan adalah ... (pilih semua yang benar).","analisis":["Tepat. Perubahan penguasaan Malaka memengaruhi perpindahan sebagian arus niaga.","Tidak tepat. Kegiatan perdagangan terus berlangsung melalui pusat-pusat lain.","Tepat. Aceh dan Banten berkembang dalam perubahan jalur perdagangan.","Tepat. Permintaan lada berkaitan dengan perluasan penanaman dan dampak pada penduduk.","Tidak tepat. Kebijakan penguasa dan konflik politik juga memengaruhi perdagangan lada."],"strategi":["Susun rantai sebab-akibat: perubahan kekuasaan -> pergeseran jalur -> muncul pusat baru.","Pilih opsi yang sesuai bagian tertentu dari rantai tersebut.","Jangan mengira perpindahan jalur sama dengan berhentinya seluruh perdagangan."],"rujukan":{"label":"BPCB Banten - Lada pada Masa Kesultanan Banten","url":"https://kebudayaan.kemdikbud.go.id/bpcbbanten/artikel-lada-banten-3-lada-pada-masa-kesultanan-banten/","umum":false},"opsi":["Perubahan politik di Malaka ikut memengaruhi jalur perdagangan kawasan.","Perdagangan rempah berhenti di seluruh Nusantara setelah 1511.","Aceh dan Banten memperoleh peluang berkembang sebagai simpul perdagangan.","Permintaan pasar dapat memengaruhi pilihan tanaman dan kehidupan ekonomi masyarakat.","Perdagangan lada tidak pernah berkaitan dengan kekuasaan dan kebijakan penguasa."],"kunci":["A","C","D"]},{"no":18,"tipe":"BS","judul":"Mataram Islam dan tradisi Sekaten","stimulus":"Tradisi Sekaten sudah dikenal sejak masa Demak dan dilanjutkan oleh kerajaan-kerajaan Islam di Jawa, termasuk Mataram. Di Keraton Yogyakarta, Sekaten dilaksanakan untuk memperingati kelahiran Nabi Muhammad. Gamelan dan kegiatan keraton menjadi bagian dari penyelenggaraannya.","tanya":"Tentukan Benar atau Salah pada pernyataan berikut.","analisis":["Benar. Tradisi tersebut disebut berlangsung sejak Demak dan dilanjutkan kemudian.","Salah. Gamelan merupakan salah satu unsur budaya yang justru tetap hadir.","Benar. Sekaten memadukan peringatan keagamaan dan ekspresi budaya setempat."],"strategi":["Perhatikan kata yang menunjukkan kesinambungan: \"sejak\", \"dilanjutkan\", \"hingga kini\".","Kenali dua unsur yang hadir bersama, yaitu agama dan budaya setempat.","Tolak opsi yang berlawanan dengan bukti penggunaan gamelan."],"rujukan":{"label":"Keraton Yogyakarta - Syiar Islam Melalui Sekaten","url":"https://www.kratonjogja.id/hajad-dalem/12-syiar-islam-melalui-sekaten/","umum":false},"pernyataan":["Sekaten menunjukkan kesinambungan tradisi dari beberapa masa kerajaan Islam di Jawa.","Penggunaan gamelan membuktikan seluruh unsur budaya lokal dibuang dalam kegiatan Sekaten.","Sekaten dapat dikaji sebagai pertemuan antara kegiatan keagamaan dan tradisi budaya Jawa."],"kunci":["B","S","B"],"label":"benar"},{"no":19,"tipe":"MC","judul":"Ternate-Tidore dan jaringan rempah","stimulus":"Ternate dan Tidore berkembang di kawasan penghasil cengkeh yang menarik pedagang berbagai wilayah. Hubungan niaga mempertemukan penguasa lokal dengan pendatang. Dalam perkembangannya, kedua kesultanan menerima pengaruh Islam dan membangun hubungan politik yang tidak selalu sama dengan kekuatan asing.","tanya":"Pernyataan yang dapat didukung oleh bacaan adalah ... (pilih semua jawaban benar).","analisis":["Tepat. Cengkeh merupakan komoditas penting dalam jaringan perdagangan.","Tepat. Interaksi niaga memungkinkan pertukaran gagasan dan budaya.","Tidak tepat. Dua kesultanan merupakan pelaku politik yang dapat mengambil langkah berbeda.","Tepat. Kerja sama dan persaingan dapat berubah mengikuti keadaan.","Tidak tepat. Penguasa dan masyarakat setempat tetap memiliki peran aktif."],"strategi":["Pisahkan tiga aspek: ekonomi rempah, pertukaran budaya, dan pilihan politik.","Periksa setiap opsi memakai minimal satu bukti dari stimulus.","Jangan menerima pernyataan \"selalu sama\" atau \"tidak punya peran\" tanpa bukti."],"rujukan":{"label":"Direktorat Pelindungan Kebudayaan - Ternate dan Tidore","url":"https://kebudayaan.kemdikbud.go.id/dpk/ternate-dan-tidore-kuali-peleburan-bangsa-bangsa/","umum":false},"opsi":["Nilai ekonomi cengkeh membantu menjelaskan mengapa kawasan ini diminati pedagang asing.","Hubungan dagang dapat membawa pertemuan budaya serta perkembangan keagamaan.","Semua keputusan penguasa Ternate dan Tidore selalu identik.","Hubungan politik dan perdagangan dapat berubah sesuai kepentingan masing-masing pihak.","Kedatangan pedagang asing membuat penduduk setempat sama sekali tidak mempunyai peran."],"kunci":["A","B","D"]},{"no":20,"tipe":"PG","judul":"Warisan budaya Islam Nusantara","stimulus":"Sejumlah masjid kuno di Nusantara menggunakan atap tumpang, tiang kayu, dan ragam hias setempat. Ciri-ciri ini menunjukkan bagaimana bangunan tempat ibadah berkembang dengan memanfaatkan bahan, keterampilan, dan tradisi arsitektur dari lingkungan masyarakatnya.","tanya":"Makna sejarah yang paling tepat dari bentuk masjid-masjid tersebut adalah ...","analisis":["Tidak tepat. Bentuk rumah ibadah berbeda mengikuti konteks tempat dan masa.","Tidak tepat. Keahlian arsitektur setempat justru tampak dalam bangunan tersebut.","Tepat. Atap, bahan, dan ornamen memperlihatkan pengolahan tradisi setempat.","Tidak tepat. Masjid kuno dibangun pada masa serta wilayah yang berbeda.","Tidak tepat. Bentuk bangunan merupakan salah satu petunjuk pertemuan budaya."],"strategi":["Amati bukti fisik: atap, tiang, bahan, dan hiasan.","Cari pilihan yang menjelaskan pertemuan pengaruh baru dengan kebudayaan lokal.","Hindari kesimpulan terlalu umum tentang seluruh masjid atau semua masyarakat."],"rujukan":{"label":"BPK Wilayah V - Masjid Agung Pondok Tinggi","url":"https://kebudayaan.kemdikbud.go.id/bpcbjambi/masjid-agung-pondok-tinggi/","umum":false},"opsi":["Seluruh masjid di dunia wajib dibangun dengan bentuk yang sama.","Masyarakat Nusantara tidak memiliki kemampuan membangun sebelum Islam datang.","Perkembangan Islam di Nusantara dapat berinteraksi dengan tradisi arsitektur setempat.","Semua masjid kuno dibuat pada tahun yang sama dan oleh penguasa yang sama.","Bangunan sejarah tidak dapat menunjukkan proses pertemuan budaya."],"kunci":["C"]}],"2":[{"no":1,"tipe":"PG","judul":"Motif penjelajahan samudra","stimulus":"Pada akhir abad ke-15, rempah-rempah dari Asia sangat diminati di Eropa. Jalur dagang yang melibatkan banyak perantara membuat harga tinggi. Di saat yang sama, kemampuan navigasi dan pembuatan kapal berkembang, sementara kerajaan-kerajaan Eropa bersaing memperluas perdagangan.","tanya":"Tujuan ekonomi yang paling langsung mendorong pelayaran bangsa Eropa menuju Asia adalah ...","analisis":["Tepat. Akses langsung ke pusat komoditas menjadi insentif ekonomi penting bagi penjelajahan samudra.","Tidak tepat. Perkembangan pelayaran justru memperkuat pencarian jalur laut.","Tidak tepat. Motif ini bukan tujuan dagang langsung yang ditunjukkan stimulus.","Tidak tepat. Rempah dicari sebagai komoditas bernilai tinggi, bukan pengganti semua pangan.","Tidak tepat. Persaingan antarkerajaan justru ikut mendorong ekspedisi."],"strategi":["Pisahkan motif ekonomi dari motif politik dan agama.","Temukan petunjuk: harga tinggi, banyak perantara, serta akses perdagangan.","Hindari jawaban yang mutlak seperti seluruh atau semua jika bukti tidak mendukung."],"rujukan":{"label":"Kemendikbud - Modul Penjelajahan Bangsa Barat","url":"https://repositori.kemendikdasmen.go.id/20592/","umum":false},"opsi":["Membangun hubungan dagang langsung agar pasokan rempah tidak selalu bergantung pada perantara.","Menghapus kebutuhan akan perdagangan laut karena jalur darat sudah lebih cepat.","Menyatukan semua kerajaan Asia di bawah pemerintahan yang sama.","Menggantikan seluruh tanaman pangan Eropa dengan rempah-rempah.","Menghindari persaingan antarkerajaan Eropa melalui penutupan pelabuhan."],"kunci":["A"]},{"no":2,"tipe":"PG","judul":"Kronologi jalur pelayaran","stimulus":"Skema kronologi berikut merangkum tiga tonggak pelayaran: Portugis menguasai Malaka (1511), pelaut Portugis mencapai kawasan Maluku (1512), dan rombongan Belanda pimpinan Cornelis de Houtman tiba di Banten (1596). Rangkaian peristiwa ini tidak menggambarkan semua pelayaran, tetapi menunjukkan meningkatnya persaingan menuju pusat perdagangan Asia. 1511 1512 1596 Portugis - Malaka Portugis - Maluku Belanda - Banten","tanya":"Kesimpulan yang paling sesuai dengan urutan peristiwa tersebut adalah ...","analisis":["Tidak tepat. Tahun 1596 datang setelah 1511 dan 1512.","Tepat. Kronologi membuktikan kedatangan Portugis mendahului pelayaran Belanda ke Banten.","Tidak tepat. Satu pelabuhan strategis tidak sama dengan kekuasaan atas semua pelabuhan.","Tidak tepat. Pedagang Asia tetap berperan dalam jaringan perdagangan.","Tidak tepat. Masing-masing ekspedisi memiliki konteks dan kepentingan beragam."],"strategi":["Urutkan tiga tahun lebih dulu sebelum membaca pilihan.","Bandingkan pernyataan dengan jangkauan bukti: peristiwa, kawasan, dan waktu.","Tolak generalisasi besar yang tidak terbukti hanya dari tiga tonggak."],"rujukan":{"label":"Kemendikbud - Modul Penjelajahan Bangsa Barat","url":"https://repositori.kemendikdasmen.go.id/20592/","umum":false},"opsi":["Belanda telah berada di Banten sebelum Portugis menguasai Malaka.","Portugis menjelajahi kawasan rempah lebih dahulu, kemudian Belanda ikut memasuki jaringan perdagangan Nusantara.","Penaklukan Malaka membuktikan seluruh pusat dagang Nusantara langsung berada di bawah Portugis.","Kedatangan Belanda pada 1596 mengakhiri semua kegiatan perdagangan bangsa Asia.","Setiap ekspedisi bangsa Eropa menempuh rute dan tujuan politik yang persis sama."],"kunci":["B"]},{"no":3,"tipe":"MC","judul":"Perubahan jaringan perdagangan","stimulus":"Sebelum datangnya armada Eropa, pedagang dari berbagai kawasan telah aktif di pelabuhan Nusantara. Ketika kapal-kapal Portugis dan Belanda ikut berdagang, sebagian penguasa pelabuhan menjalin persekutuan baru, sedangkan sebagian lainnya menghadapi tekanan monopoli. Jaringan dagang lama tidak langsung lenyap.","tanya":"Pernyataan manakah yang didukung oleh stimulus? Pilih semua jawaban yang benar.","analisis":["Tepat. Masuknya pedagang Eropa memperluas persaingan dalam jejaring yang sudah ada.","Tidak tepat. Stimulus secara jelas menyebut jaringan lama tidak langsung lenyap.","Tepat. Aliansi dan tekanan perdagangan dapat memengaruhi politik pelabuhan.","Tidak tepat. Respons penguasa beragam, termasuk penolakan monopoli.","Tepat. Ada perubahan pelaku, tetapi perdagangan antarkawasan tetap berlangsung."],"strategi":["Dalam MCMA, uji tiap opsi secara mandiri, bukan mencari satu yang paling baik.","Cari bukti eksplisit untuk setiap klaim, terutama kata sebagian dan tidak langsung.","Perhatikan konsep perubahan sekaligus keberlanjutan."],"rujukan":{"label":"Kemendikbud - Modul Penjelajahan Bangsa Barat","url":"https://repositori.kemendikdasmen.go.id/20592/","umum":false},"opsi":["Kedatangan armada Eropa menambah pelaku dan kepentingan dalam jaringan dagang.","Perdagangan antarmasyarakat Asia langsung berhenti di semua pelabuhan.","Hubungan ekonomi dapat berpengaruh pada pilihan politik penguasa setempat.","Semua kesultanan selalu menyambut monopoli tanpa perlawanan.","Perubahan jaringan dagang berlangsung bersama unsur keberlanjutan."],"kunci":["A","C","E"]},{"no":4,"tipe":"BS","judul":"Menilai perubahan dan keberlanjutan","stimulus":"Rekonstruksi bahan bacaan: (I) Sebelum abad ke-16, beberapa pelabuhan Nusantara dikunjungi pedagang Asia dan memiliki jaringan pemasaran rempah. (II) Sejak abad ke-16 hingga ke-17, sejumlah kekuatan Eropa berusaha mengendalikan simpul perdagangan, meski aktivitas pedagang Asia tetap berlangsung. Kedua ringkasan menggambarkan rentang dan wilayah yang berbeda.","tanya":"Nilailah ketepatan tiap kesimpulan berdasarkan kedua informasi tersebut.","analisis":["Tepat. Masuknya kekuatan Eropa mengubah persaingan atas pengendalian perdagangan.","Tidak Tepat. Bacaan menyebut pedagang Asia tetap aktif, sehingga klaim punah tidak didukung.","Tepat. Perbandingan lintas waktu memungkinkan penilaian perubahan dan unsur yang bertahan."],"strategi":["Tentukan apa yang berubah dan apa yang masih berlanjut.","Bedakan bukti terbatas dari klaim mutlak tentang semua wilayah.","Untuk kategori, putuskan Tepat/Tidak Tepat pada tiap baris secara terpisah."],"rujukan":{"label":"Kemendikbud - Modul Penjelajahan Bangsa Barat","url":"https://repositori.kemendikdasmen.go.id/20592/","umum":false},"pernyataan":["Ada perubahan dalam pihak yang berupaya menguasai jalur perdagangan.","Jaringan pedagang Asia pasti punah sepenuhnya setelah kedatangan Eropa.","Membandingkan dua periode dapat membantu mengidentifikasi perubahan dan keberlanjutan."],"kunci":["B","S","B"],"label":"tepat"},{"no":5,"tipe":"PG","judul":"VOC dan hak oktroi","stimulus":"VOC didirikan pada 1602 sebagai kongsi dagang Belanda. Pemerintah Belanda memberikan hak khusus atau oktroi, antara lain menjalankan monopoli dagang, membangun benteng, membuat perjanjian, serta memiliki angkatan bersenjata. Hak-hak itu membuat VOC mampu bertindak lebih jauh daripada perusahaan dagang biasa. DAGANG DIPLOMASI MILITER Monopoli Perjanjian Benteng & tentara","tanya":"Mengapa hak oktroi berpengaruh besar terhadap posisi VOC di Nusantara?","analisis":["Tidak tepat. Hak oktroi justru melampaui jual beli semata.","Tidak tepat. Hak khusus tidak membuat semua kerajaan langsung kehilangan kedaulatan.","Tepat. Kombinasi monopoli, perjanjian, benteng, dan tentara memberi VOC daya tekan yang kuat.","Tidak tepat. VOC memperoleh hak khusus dari otoritas Belanda, bukan dari semua kerajaan Nusantara.","Tidak tepat. Kewenangan mengadakan perjanjian termasuk hak VOC."],"strategi":["Kelompokkan hak oktroi menjadi ekonomi, diplomasi, dan militer.","Pilih opsi yang menjelaskan mekanisme kekuasaan, bukan sekadar nama lembaganya.","Waspadai kata otomatis dan semua yang melampaui bukti."],"rujukan":{"label":"Kemendikbud - Modul Penjajahan Bangsa Eropa","url":"https://repositori.kemendikdasmen.go.id/21588/","umum":false},"opsi":["Karena VOC hanya boleh membeli barang tanpa ikut menentukan aturan perdagangan.","Karena hak oktroi menghapus seluruh pengaruh kerajaan lokal secara otomatis.","Karena VOC memiliki perangkat ekonomi, diplomatik, dan militer untuk memperkuat pengaruhnya.","Karena semua hak politik VOC selalu dikendalikan langsung oleh kerajaan Nusantara.","Karena hak oktroi melarang VOC membentuk perjanjian dengan penguasa lokal."],"kunci":["C"]},{"no":6,"tipe":"MC","judul":"Hongi dan ekstirpasi di Maluku","stimulus":"Dalam perdagangan rempah Maluku, VOC menjalankan pelayaran hongi untuk mengawasi kepatuhan terhadap monopoli. VOC juga menerapkan ekstirpasi atau pembatasan tanaman rempah, termasuk melalui pemusnahan pohon tertentu, guna mengendalikan pasokan. Kebijakan ini menimbulkan tekanan bagi banyak produsen setempat.","tanya":"Akibat yang masuk akal berdasarkan kebijakan tersebut adalah ... Pilih semua jawaban benar.","analisis":["Tepat. Monopoli membatasi pilihan pembeli dan ruang tawar produsen.","Tidak tepat. Pengendalian oleh VOC justru mengurangi otonomi harga produsen.","Tidak tepat. Hongi adalah sarana pengawasan, bukan penghapusan pengawasan.","Tepat. Ekstirpasi dipakai sebagai alat pengaturan produksi dan pasokan.","Tepat. Pembatasan ekonomi dapat menjadi pemicu konflik kepentingan."],"strategi":["Hubungkan kebijakan dengan akibatnya melalui sebab-akibat yang jelas.","Tanyakan: pihak mana mengendalikan perdagangan dan siapa terkena dampaknya?","Dalam MCMA, tandai pilihan yang bisa disimpulkan, bukan yang sekadar terdengar positif."],"rujukan":{"label":"Kemendikbud - Modul Penjajahan Bangsa Eropa","url":"https://repositori.kemendikdasmen.go.id/21588/","umum":false},"opsi":["Kebebasan penduduk menjual rempah ke pembeli lain dapat dibatasi.","Produsen rempah memperoleh hak penuh menetapkan harga pasar internasional.","Pelayaran hongi bertujuan utama menghapus semua bentuk pengawasan dagang.","Pembatasan jumlah tanaman dapat digunakan untuk mengendalikan pasokan rempah.","Pengawasan monopoli berpotensi memicu ketegangan antara VOC dan masyarakat setempat."],"kunci":["A","D","E"]},{"no":7,"tipe":"BS","judul":"Intervensi VOC dalam politik lokal","stimulus":"Rekonstruksi kasus: Dua kelompok elite kesultanan berselisih tentang pergantian takhta. VOC menawarkan bantuan kepada salah satu pihak dengan imbalan hak dagang dan izin membangun benteng. Setelah pihak yang dibantu menang, VOC menuntut pelaksanaan perjanjian. Kasus ini menyederhanakan pola intervensi yang muncul di beberapa kerajaan Nusantara.","tanya":"Tentukan Tepat atau Tidak Tepat untuk pernyataan berikut.","analisis":["Tepat. Konflik elite menjadi pintu masuk intervensi ketika VOC mendukung salah satu pihak.","Tepat. Imbalan berupa hak dagang dan benteng merupakan pengaruh ekonomi-politik.","Tidak Tepat. Kesepakatan elite tidak berarti semua lapisan masyarakat mendukungnya."],"strategi":["Bedakan aktor yang menandatangani perjanjian dari seluruh penduduk.","Ikuti urutan: konflik, intervensi, imbalan, dampak.","Jangan menganggap kemenangan politik sama dengan persetujuan universal."],"rujukan":{"label":"Kemendikbud - Modul Penjajahan Bangsa Eropa","url":"https://repositori.kemendikdasmen.go.id/21588/","umum":false},"pernyataan":["Persaingan elite lokal dapat membuka peluang campur tangan kekuatan luar.","Bantuan militer dapat ditukar dengan keuntungan ekonomi dan politik.","Kemenangan satu pihak pasti membuktikan seluruh rakyat menyetujui hak monopoli VOC."],"kunci":["B","B","S"],"label":"tepat"},{"no":8,"tipe":"PG","judul":"Daendels, Raffles, dan Tanam Paksa","stimulus":"Tabel ringkas kebijakan: Daendels (1808-1811) memperkuat pertahanan dan administrasi kolonial; Raffles (1811-1816) memperkenalkan gagasan sewa tanah; pemerintah Hindia Belanda menerapkan sistem Tanam Paksa sejak 1830 untuk meningkatkan penerimaan kolonial. Praktik di lapangan tidak selalu sama dengan rancangan resmi. 1808-1811 1811-1816 Sejak 1830 Daendels Raffles Tanam Paksa Pertahanan & administrasi Sewa tanah Tanaman ekspor & pendapatan","tanya":"Kesimpulan yang paling tepat dari perbandingan kebijakan tersebut adalah ...","analisis":["Tidak tepat. Tujuan kebijakan dan instrumennya berbeda pada tiap periode.","Tepat. Urutan tersebut menunjukkan pergeseran penekanan administrasi dan penggalian pendapatan.","Tidak tepat. Masa Raffles mendahului penerapan Tanam Paksa.","Tidak tepat. Tahun 1830 datang setelah 1808-1811.","Tidak tepat. Masa Raffles terbatas pada 1811-1816."],"strategi":["Gunakan tahun sebagai jangkar urutan.","Bedakan tujuan kebijakan dari dampak praktiknya.","Cari pernyataan yang merangkum perbandingan, bukan menyamakan semuanya."],"rujukan":{"label":"Kemendikbud - Modul Dampak Penjajahan","url":"https://repositori.kemendikdasmen.go.id/22010/","umum":false},"opsi":["Ketiganya menjalankan kebijakan yang sama persis tanpa perubahan sasaran.","Prioritas kolonial berubah dari penguatan pertahanan/administrasi ke pendapatan tanah dan produksi ekspor.","Sewa tanah diperkenalkan setelah sistem Tanam Paksa berakhir.","Tanam Paksa lebih dahulu diterapkan daripada pemerintahan Daendels.","Raffles memimpin pemerintahan Hindia Belanda selama seluruh abad ke-19."],"kunci":["B"]},{"no":9,"tipe":"MC","judul":"Evaluasi sistem Tanam Paksa","stimulus":"Ringkasan kajian: Sistem Tanam Paksa diterapkan sejak 1830 untuk memperoleh hasil tanaman ekspor bagi pemerintah kolonial. Aturan tertulis memuat pembatasan tertentu, tetapi di sejumlah tempat pelaksanaan menyimpang dan menambah beban petani. Penerimaan negara kolonial meningkat, sementara dampak bagi penduduk berbeda-beda menurut wilayah dan praktik setempat.","tanya":"Penilaian manakah yang dapat dipertanggungjawabkan dari ringkasan tersebut? Pilih semua jawaban benar.","analisis":["Tepat. Penyimpangan lapangan membuat rumusan resmi tidak cukup untuk membaca dampaknya.","Tidak tepat. Pendapatan negara tidak otomatis menunjukkan kesejahteraan semua petani.","Tepat. Dua akibat tersebut dapat terjadi secara bersamaan pada pihak berbeda.","Tidak tepat. Dampak lokal disebut beragam, bukan seragam.","Tepat. Membandingkan bukti lokal mencegah penyederhanaan dampak kolonial."],"strategi":["Cari siapa yang memperoleh manfaat dan siapa yang menanggung biaya.","Bedakan rancangan kebijakan, pelaksanaan, dan akibat.","Hindari generalisasi dari penerimaan kolonial ke seluruh masyarakat."],"rujukan":{"label":"Kemendikbud - Modul Dampak Penjajahan","url":"https://repositori.kemendikdasmen.go.id/22010/","umum":false},"opsi":["Aturan formal dan praktik pelaksanaan harus dibedakan ketika menilai kebijakan.","Keuntungan fiskal pemerintah kolonial membuktikan kesejahteraan semua petani meningkat.","Peningkatan penerimaan kolonial dapat berlangsung bersamaan dengan beban rakyat.","Setiap desa mengalami dampak identik sehingga tidak perlu penelitian lokal.","Kesimpulan tentang dampak sosial perlu mempertimbangkan ragam bukti wilayah."],"kunci":["A","C","E"]},{"no":10,"tipe":"PG","judul":"Ternate menentang Portugis","stimulus":"Hubungan Ternate dengan Portugis memburuk akibat monopoli dan campur tangan politik. Sultan Khairun dibunuh pada 1570. Putranya, Sultan Baabullah, kemudian memimpin pengepungan benteng Portugis hingga kekuatan Portugis meninggalkan Ternate pada 1575.","tanya":"Peristiwa yang secara langsung memperkuat perlawanan di bawah Sultan Baabullah adalah ...","analisis":["Tidak tepat. Peristiwa tersebut terjadi jauh sesudah abad ke-16.","Tidak tepat. Perjanjian Bongaya berkaitan dengan Gowa dan VOC pada 1667.","Tidak tepat. Tanam Paksa dimulai 1830.","Tepat. Pembunuhan Sultan Khairun menjadi pemicu eskalasi perlawanan yang dipimpin putranya.","Tidak tepat. Kedatangan Belanda ke Banten terjadi lebih kemudian dan bukan pemicu langsung."],"strategi":["Identifikasi aktor dan wilayah: Ternate, Portugis, Baabullah.","Gunakan kronologi untuk menyingkirkan peristiwa beda abad.","Cari pemicu langsung, bukan kejadian kolonial lain yang sama-sama penting."],"rujukan":{"label":"Kemendikbud - Jejak Purbakala Maluku (topik terkait)","url":"https://repositori.kemendikdasmen.go.id/14584/1/Buku%20jejak%20peninggalan%20sejarah%20purbakala%20di%20kepulauan%20maluku.pdf","umum":false},"opsi":["Pengangkatan Daendels sebagai gubernur jenderal pada awal abad ke-19.","Penandatanganan Perjanjian Bongaya di Sulawesi Selatan.","Pelaksanaan Tanam Paksa oleh pemerintah Hindia Belanda.","Pembunuhan Sultan Khairun yang memperdalam konflik Ternate dengan Portugis.","Kedatangan armada Belanda di Banten pada 1596."],"kunci":["D"]},{"no":11,"tipe":"BS","judul":"Gowa dan Perjanjian Bongaya","stimulus":"Kesultanan Gowa merupakan kekuatan perdagangan penting di timur Nusantara. Sultan Hasanuddin menolak tekanan monopoli VOC. Konflik berakhir dengan perjanjian Bongaya pada 1667 yang membatasi pengaruh Gowa dan memperkuat posisi VOC dalam perdagangan kawasan tersebut.","tanya":"Nilailah ketepatan setiap pernyataan tentang konflik Gowa dan VOC.","analisis":["Tepat. Pelabuhan strategis dan monopoli menjadi inti persaingan kekuasaan.","Tidak Tepat. Perjanjian justru memperkuat posisi VOC dan membatasi Gowa.","Tepat. Hasil konflik militer diformalkan melalui perjanjian yang memengaruhi posisi politik dan dagang."],"strategi":["Bedakan kepentingan dagang dari isi dan akibat perjanjian.","Bandingkan setiap pernyataan dengan arah perubahan kekuasaan.","Jangan menyamakan perjanjian dengan kesetaraan posisi pihak-pihaknya."],"rujukan":{"label":"Pusmendik - TKA Sejarah","url":"https://pusmendik.kemdikbud.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"pernyataan":["Posisi Gowa sebagai pusat perdagangan membantu menjelaskan kepentingan VOC menguasainya.","Perjanjian Bongaya memperluas kebebasan Gowa untuk mengusir seluruh pengaruh VOC.","Perjanjian dapat menjadi alat perubahan kekuasaan tanpa menghilangkan pentingnya konflik militer."],"kunci":["B","S","B"],"label":"tepat"},{"no":12,"tipe":"PG","judul":"Banten dan konflik elite","stimulus":"Pada akhir abad ke-17, perselisihan antara Sultan Ageng Tirtayasa dan Sultan Haji melemahkan kesatuan politik Banten. Sultan Haji memperoleh dukungan VOC, sedangkan hubungan VOC dengan pihak Sultan Ageng berkonflik. Dalam situasi tersebut VOC memperoleh peluang memperluas pengaruhnya terhadap Banten.","tanya":"Penjelasan sebab-akibat yang paling tepat berdasarkan informasi tersebut adalah ...","analisis":["Tepat. Dukungan VOC pada pihak tertentu meningkatkan posisi tawar politik dan ekonomi VOC.","Tidak tepat. Konflik elite tidak berarti seluruh struktur masyarakat dan wilayah hilang.","Tidak tepat. Perbedaan posisi kedua tokoh merupakan inti stimulus.","Tidak tepat. VOC memiliki kepentingan perdagangan dan pengaruh politik.","Tidak tepat. Perang Aceh berlangsung jauh kemudian dalam konteks berbeda."],"strategi":["Tandai pihak yang berkonflik, sekutu, dan keuntungan yang diperoleh.","Jelaskan hubungan konflik internal dengan intervensi eksternal.","Gunakan ruang dan waktu untuk menguji pengalih perhatian."],"rujukan":{"label":"ANRI - Sejarah Nusantara, Korespondensi Banten (topik terkait)","url":"https://sejarah-nusantara.anri.go.id/id/search_letters/?q=&ruler=Sultan+Haji","umum":false},"opsi":["Persaingan internal memberi VOC kesempatan ikut menentukan arah politik dan hubungan dagang Banten.","Konflik keluarga secara otomatis membuat Banten tidak lagi memiliki rakyat dan wilayah.","Sultan Ageng dan Sultan Haji selalu memiliki sikap yang sama terhadap VOC.","VOC sama sekali tidak berkepentingan dalam dinamika politik Banten.","Konflik Banten terjadi karena perang Aceh melawan Belanda tahun 1873."],"kunci":["A"]},{"no":13,"tipe":"MC","judul":"Pattimura dan perlawanan Saparua","stimulus":"Setelah wilayah Maluku kembali berada di bawah pemerintahan Belanda, ketidakpuasan terhadap kebijakan kolonial berkembang di Saparua. Pada 1817, perlawanan yang dipimpin Thomas Matulessy atau Kapitan Pattimura menyerang Benteng Duurstede. Perlawanan ini berkaitan dengan tekanan ekonomi dan pemerintahan kolonial.","tanya":"Pernyataan manakah yang sesuai dengan konteks perlawanan Pattimura? Pilih semua jawaban benar.","analisis":["Tepat. Ketidakpuasan sosial-ekonomi dan kontrol politik menjadi konteks perlawanan.","Tepat. Serangan terhadap Benteng Duurstede merupakan peristiwa penting perlawanan Saparua.","Tidak tepat. Pemimpin Gowa berbeda masa dan wilayah dari Pattimura.","Tepat. Perubahan rezim kolonial dapat berdampak pada kerja, perdagangan, dan pemerintahan lokal.","Tidak tepat. Tahun 1817 jauh mendahului Proklamasi 1945."],"strategi":["Pasangkan tokoh, tempat, dan waktu sebelum menarik kesimpulan.","Hubungkan dampak kebijakan dengan sasaran perlawanan.","Uji opsi yang tampak mirip tetapi berasal dari konflik lain."],"rujukan":{"label":"Bea Cukai Ambon - Sejarah Benteng Duurstede","url":"https://ambon.beacukai.go.id/galeri/mengenal-sejarah-benteng-duurstede","umum":false},"opsi":["Perlawanan dapat dipahami sebagai respons terhadap beban dan kontrol kolonial.","Benteng Duurstede menjadi salah satu sasaran penting dalam perlawanan 1817.","Perlawanan Pattimura dipimpin oleh Sultan Hasanuddin dari Gowa.","Pergantian pemerintahan kolonial dapat mengubah kebijakan yang dialami warga.","Tahun 1817 menunjukkan perlawanan terjadi sesudah Indonesia merdeka."],"kunci":["A","B","D"]},{"no":14,"tipe":"BS","judul":"Diponegoro: banyak lapisan penyebab","stimulus":"Sumber ringkas A mencatat pemasangan patok jalan yang melintasi area makam leluhur Diponegoro di Tegalrejo pada 1825. Sumber ringkas B menjelaskan keresahan lebih luas: campur tangan kolonial dalam urusan istana, tekanan pajak, dan masalah sosial-keagamaan. Perang Jawa berlangsung 1825-1830.","tanya":"Nilailah kesimpulan yang paling dapat dipertanggungjawabkan dari kedua ringkasan.","analisis":["Tepat. Patok jalan menjadi pemicu langsung dalam situasi ketegangan yang telah berkembang.","Tepat. Kedua ringkasan menunjukkan lapisan sebab yang saling berkaitan.","Tidak Tepat. Motif peserta perlawanan tidak dapat digeneralisasi hanya dari satu peristiwa."],"strategi":["Bedakan sebab jangka panjang dengan pemicu langsung.","Rangkai bukti dari lebih dari satu sumber sebelum menyimpulkan.","Tolak klaim semua jika bukti menggambarkan keragaman kepentingan."],"rujukan":{"label":"Kemendikbud - Perlawanan Bangsa Indonesia","url":"https://repositori.kemendikdasmen.go.id/20593/1/Kelas%20XI_Sejarah%20Indonesia_KD%203.6.pdf","umum":false},"pernyataan":["Persoalan patok jalan dapat dipahami sebagai pemicu dekat dalam konflik yang lebih luas.","Sebab perang perlu ditafsirkan dengan melihat unsur politik, ekonomi, dan sosial selain pemicu langsung.","Satu insiden membuktikan seluruh pengikut Diponegoro memiliki alasan yang identik."],"kunci":["B","B","S"],"label":"tepat"},{"no":15,"tipe":"PG","judul":"Aceh dan perlawanan abad ke-19","stimulus":"Perang Aceh dimulai pada 1873. Perlawanan melibatkan beragam unsur masyarakat, antara lain elite kesultanan, ulama, dan jaringan pejuang setempat. Kondisi geografis serta dukungan masyarakat memberi pengaruh terhadap kelangsungan perlawanan, yang berlanjut melampaui abad ke-19.","tanya":"Ciri yang paling sesuai dengan gambaran perlawanan Aceh tersebut adalah ...","analisis":["Tidak tepat. Perang Aceh berlangsung lama dan melibatkan banyak unsur masyarakat.","Tidak tepat. Bentuk organisasi dan cara berjuang berbeda dari tentara kolonial Eropa.","Tidak tepat. Perang dimulai 1873, bukan sebelum 1511.","Tidak tepat. VOC telah dibubarkan sebelum perang dimulai.","Tepat. Jaringan sosial, pemimpin lokal, dan medan membantu memahami panjangnya perlawanan."],"strategi":["Tentukan tahun awal serta tokoh/kelompok yang disebut.","Ingat perbedaan VOC dan pemerintahan kolonial abad ke-19.","Cari ciri yang didukung oleh beberapa petunjuk stimulus."],"rujukan":{"label":"Kemendikbud - Modul Perlawanan Nusantara","url":"https://repositori.kemendikdasmen.go.id/20212/","umum":false},"opsi":["Hanya berlangsung satu hari dan tanpa dukungan masyarakat.","Seluruh pejuang beroperasi sebagai satu unit tentara Eropa.","Terjadi sebelum Portugis menguasai Malaka tahun 1511.","Dikendalikan sepenuhnya oleh VOC yang sudah bubar pada 1799.","Melibatkan jaringan pemimpin dan kelompok lokal dalam perjuangan yang berkepanjangan."],"kunci":["E"]},{"no":16,"tipe":"MC","judul":"Perang Banjar dan intervensi kolonial","stimulus":"Perselisihan suksesi di Kesultanan Banjar meningkat ketika pemerintah Belanda mendukung pengangkatan Tamjidillah sebagai sultan pada 1857. Ketidakpuasan terhadap campur tangan politik dan kepentingan ekonomi kolonial memperbesar ketegangan. Perlawanan pada 1859 dipimpin antara lain oleh Pangeran Antasari dan melibatkan berbagai kelompok masyarakat.","tanya":"Analisis manakah yang sesuai dengan latar Perang Banjar? Pilih semua jawaban benar.","analisis":["Tepat. Campur tangan dalam suksesi menjadi salah satu sumber ketidakpuasan.","Tidak tepat. Pendudukan Jepang berlangsung jauh setelah peristiwa 1859.","Tepat. Kepentingan ekonomi dan legitimasi politik dapat saling memperkuat.","Tepat. Pangeran Antasari dan jaringan lokal terkait langsung dengan konteks kesultanan.","Tidak tepat. Dukungan kolonial justru diikuti ketegangan dan perlawanan."],"strategi":["Hubungkan kebijakan politik kolonial dengan respons kelompok lokal.","Uji konsistensi tahun untuk menyingkirkan anakronisme.","Lihat faktor politik dan ekonomi sebagai kemungkinan sebab bersama."],"rujukan":{"label":"UIN Sunan Kalijaga - Perang Banjar 1859-1862","url":"https://digilib.uin-suka.ac.id/id/eprint/796/","umum":false},"opsi":["Intervensi dalam pergantian takhta ikut memperuncing konflik politik setempat.","Perang Banjar timbul karena pendudukan Jepang pada abad ke-20.","Kepentingan ekonomi kolonial dapat saling terkait dengan persoalan legitimasi penguasa.","Perlawanan dipimpin tokoh setempat dan tidak dapat dipisahkan dari dinamika Kesultanan Banjar.","Dukungan Belanda kepada calon sultan membuktikan tidak ada penolakan dari masyarakat."],"kunci":["A","C","D"]},{"no":17,"tipe":"PG","judul":"Membandingkan sebab perlawanan","stimulus":"Perbandingan dua kasus: (1) Saparua, 1817: ketidakpuasan terhadap kebijakan kolonial dan beban ekonomi mendorong perlawanan yang dipimpin Pattimura. (2) Jawa, 1825: tekanan kolonial dan persoalan politik-istana memperbesar ketegangan; persoalan patok jalan menjadi pemicu yang dekat. SAPARUA 1817 JAWA 1825 Beban ekonomi dan kontrol kolonial Kebijakan kolonial dan konflik politik","tanya":"Persamaan yang paling tepat antara kedua perlawanan adalah ...","analisis":["Tidak tepat. Bongaya berkaitan dengan Gowa pada 1667.","Tepat. Ada pola penolakan kolonial yang sama dengan konteks lokal berlainan.","Tidak tepat. Pattimura dan Diponegoro adalah tokoh dari dua wilayah dan tahun berbeda.","Tidak tepat. Masing-masing konflik mempunyai beberapa lapis penyebab.","Tidak tepat. VOC dibubarkan pada 1799, sebelum kedua peristiwa."],"strategi":["Susun terlebih dahulu persamaan, lalu perbedaan kedua kasus.","Jangan menyamakan pemicu khusus dengan keseluruhan faktor penyebab.","Gunakan tahun 1799 sebagai batas keberadaan VOC."],"rujukan":{"label":"Kemendikbud - Modul Perlawanan Nusantara","url":"https://repositori.kemendikdasmen.go.id/20212/","umum":false},"opsi":["Keduanya berawal dari perjanjian Bongaya yang sama.","Keduanya melibatkan penolakan terhadap campur tangan kolonial, meskipun sebab khususnya berbeda.","Keduanya dipimpin oleh tokoh yang sama pada tempat dan tahun yang sama.","Keduanya semata-mata muncul akibat satu insiden dan tanpa sebab lain.","Keduanya terjadi ketika VOC masih berkuasa sebagai perusahaan dagang."],"kunci":["B"]},{"no":18,"tipe":"MC","judul":"Menilai pilihan strategi perjuangan","stimulus":"Tiga gambaran strategi: Perlawanan Diponegoro memanfaatkan mobilitas dan pengetahuan medan; perlawanan Aceh ditopang jaringan lokal dan kepemimpinan yang beragam; Gowa menggunakan kekuatan politik-dagang dan pertahanan wilayah pesisir untuk menghadapi VOC. Hasil setiap perjuangan juga dipengaruhi sumber daya lawan dan perubahan aliansi.","tanya":"Penilaian strategi yang masuk akal berdasarkan perbandingan tersebut adalah ... Pilih semua jawaban benar.","analisis":["Tepat. Medan dan mobilitas relevan bagi perang yang mengandalkan pergerakan.","Tidak tepat. Efektivitas strategi sangat bergantung situasi dan sumber daya.","Tepat. Jaringan dukungan memengaruhi logistik, informasi, dan keberlanjutan perjuangan.","Tidak tepat. Perjanjian dapat lahir dari ketimpangan kekuatan.","Tepat. Penilaian strategi yang historis harus kontekstual, bukan memakai satu rumus."],"strategi":["Analisis kecocokan antara strategi dan situasi tiap wilayah.","Bedakan tujuan perjuangan dari hasil yang akhirnya dicapai.","Tolak klaim selalu dan identik jika contoh menunjukkan keragaman."],"rujukan":{"label":"Kemendikbud - Modul Perlawanan Nusantara","url":"https://repositori.kemendikdasmen.go.id/20212/","umum":false},"opsi":["Pemahaman medan dapat menjadi keuntungan dalam perang bergerak.","Strategi paling efektif selalu sama tanpa memperhatikan geografi dan sumber daya.","Dukungan jaringan lokal membantu menjelaskan kelangsungan perlawanan.","Perjanjian setelah konflik selalu menunjukkan kedua pihak memperoleh keuntungan yang identik.","Pilihan strategi perlu dikaji bersama konteks kekuatan, aliansi, dan tujuan perjuangan."],"kunci":["A","C","E"]},{"no":19,"tipe":"BS","judul":"Faktor kekuatan dan keterbatasan","stimulus":"Rekonstruksi dua kasus: Kelompok P mengenal medan, tetapi kesulitan memperoleh logistik ketika jalur pasokan dibatasi. Kelompok Q memiliki benteng dan sumber daya awal lebih besar, tetapi terpecah akibat perubahan aliansi elite. Kedua kasus sengaja disederhanakan sebagai latihan menimbang faktor dalam konflik kolonial, bukan menggambarkan satu peristiwa tertentu.","tanya":"Tentukan ketepatan penilaian terhadap kedua kasus berikut.","analisis":["Tepat. Keberlangsungan operasi bergantung pula pada dukungan material.","Tidak Tepat. Perpecahan politik dapat mengurangi keunggulan pertahanan.","Tepat. Dua kasus memperlihatkan pentingnya sumber daya dan persatuan kepemimpinan."],"strategi":["Identifikasi kekuatan dan kelemahan tiap kasus secara terpisah.","Hindari penilaian hanya dari satu variabel seperti benteng atau medan.","Pakai bukti soal, bukan anggapan bahwa pemenang selalu memiliki strategi terbaik."],"rujukan":{"label":"Kemendikbud - Modul Perlawanan Nusantara","url":"https://repositori.kemendikdasmen.go.id/20212/","umum":false},"pernyataan":["Keunggulan medan belum tentu cukup jika pasokan makanan dan perlengkapan terganggu.","Kekuatan benteng membuktikan konflik internal dan perubahan aliansi tidak berpengaruh.","Penilaian peluang suatu perlawanan perlu mempertimbangkan logistik dan kohesi politik."],"kunci":["B","S","B"],"label":"tepat"},{"no":20,"tipe":"BS","judul":"Menguji interpretasi kolonialisme","stimulus":"Ringkasan bukti 1: Konflik Gowa-VOC terkait monopoli dagang dan berujung pada Perjanjian Bongaya (1667). Ringkasan bukti 2: Perang Banjar (1859) berkaitan dengan campur tangan kolonial pada suksesi dan kepentingan ekonomi. Seorang siswa menyatakan, \"Semua perlawanan terjadi hanya karena satu penyebab ekonomi dan memakai strategi seragam.\"","tanya":"Nilailah pernyataan yang tepat untuk menguji interpretasi siswa tersebut.","analisis":["Tepat. Monopoli dan suksesi menunjukkan keterhubungan ekonomi dengan politik.","Tidak Tepat. Dua kasus tidak membenarkan generalisasi tentang semua perlawanan.","Tepat. Kritik sumber dan konteks diperlukan agar kesimpulan tidak berlebihan."],"strategi":["Uji dahulu apakah bukti cukup untuk mendukung klaim yang sangat luas.","Perhatikan perbedaan tempat, aktor, masa, dan pemicu tiap kasus.","Pertahankan kesimpulan proporsional terhadap bukti yang tersedia."],"rujukan":{"label":"Pusmendik - TKA Sejarah","url":"https://pusmendik.kemdikbud.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"pernyataan":["Kedua bukti menunjukkan kebijakan ekonomi dapat bertaut dengan persoalan politik.","Dua kasus cukup membuktikan semua perlawanan Nusantara memiliki satu sebab dan strategi seragam.","Interpretasi yang kuat perlu mempertimbangkan konteks, waktu, dan ragam bukti sejarah."],"kunci":["B","S","B"],"label":"tepat"}],"3":[{"no":1,"tipe":"PG","judul":"Politik Etis dan kaum terpelajar","stimulus":"Pada awal abad ke-20, pemerintah kolonial memperluas sebagian kesempatan pendidikan bagi penduduk bumiputra, meskipun aksesnya tetap terbatas. Dari kelompok terdidik ini muncul tokoh-tokoh yang membaca pemikiran modern, mengkritik ketidakadilan, dan mengorganisasi perkumpulan.","tanya":"Hubungan sebab-akibat yang paling tepat antara pendidikan kolonial dan tumbuhnya kesadaran nasional adalah ...","analisis":["Keliru: kesempatan bersekolah masih timpang dan diskriminasi tetap berlangsung.","Keliru: status lulusan beragam dan tidak otomatis memperoleh jabatan tinggi.","Tepat: dampak pendidikan dapat melampaui tujuan administrasi kolonial.","Keliru: kebijakan pendidikan tidak identik dengan rencana kemerdekaan.","Keliru: pendidikan dan komunikasi justru turut membentuk jaringan gagasan."],"strategi":["Cari perbedaan antara maksud awal kebijakan dan dampak yang tidak direncanakan.","Tautkan perubahan pendidikan dengan lahirnya aktor serta organisasi.","Hindari jawaban yang memakai kata mutlak seperti \"seluruh\" atau \"semua\"."],"rujukan":{"label":"BPCB Sumatera Barat - Eksistensi Guru dan Politik Etis","url":"https://kebudayaan.kemdikbud.go.id/bpcbsumbar/eksistensi-guru-dan-politik-etis/","umum":false},"opsi":["Pendidikan kolonial dengan sendirinya menghapus seluruh diskriminasi di Hindia Belanda.","Semua lulusan sekolah kolonial langsung menjadi pejabat tinggi pemerintahan.","Pendidikan melahirkan sebagian kaum terpelajar yang kemudian menafsirkan ulang pengalaman penjajahan dan mengembangkan gerakan.","Pemerintah kolonial memang merancang pendidikan untuk segera menyerahkan kemerdekaan.","Kesadaran nasional muncul tanpa keterkaitan dengan perubahan komunikasi dan pendidikan."],"kunci":["C"]},{"no":2,"tipe":"MC","judul":"Sekolah, pers, dan jaringan organisasi","stimulus":"Ilustrasi berbasis konteks sejarah: murid dari berbagai daerah berkenalan di sekolah, lalu berdiskusi dalam perkumpulan. Tulisan mereka beredar melalui surat kabar dan majalah sehingga gagasan mengenai persamaan hak serta kebangsaan menjangkau pembaca lebih luas. Pers tetap menghadapi pengawasan kolonial.","tanya":"Pilih SEMUA simpulan yang didukung stimulus tentang lahirnya kesadaran nasional.","analisis":["Tepat: sekolah memungkinkan terbangunnya hubungan antarpelajar.","Tidak tepat: stimulus menyebut pengawasan terhadap pers.","Tepat: media cetak membawa ide melampaui pertemuan langsung.","Tidak tepat: perkumpulan turut tumbuh dari jejaring terpelajar.","Tepat: komunikasi menumbuhkan imajinasi mengenai kesamaan nasib."],"strategi":["Uji setiap opsi secara mandiri, bukan memilih satu yang terasa paling benar.","Bedakan peluang menyebarkan ide dengan kebebasan pers yang tanpa batas.","Cocokkan kata kerja setiap opsi dengan bukti yang muncul dalam stimulus."],"rujukan":{"label":"BPCB Sumatera Barat - Arti Kebangkitan Nasional","url":"https://kebudayaan.kemdikbud.go.id/bpcbsumbar/arti-kebangkitan-nasional%E2%80%8E/","umum":false},"opsi":["Pendidikan menyediakan ruang pertemuan dan pembentukan jejaring antarpelajar.","Pemerintah kolonial menjamin semua surat kabar bebas dari pembatasan.","Pers dapat membantu menyebarkan gagasan antardaerah.","Perkembangan organisasi tidak berkaitan dengan bertambahnya kaum terpelajar.","Pertukaran gagasan mendorong pandangan tentang kepentingan bersama."],"kunci":["A","C","E"]},{"no":3,"tipe":"BS","judul":"Paradoks kebijakan pendidikan kolonial","stimulus":"Pendidikan pada masa Politik Etis dikembangkan dalam struktur pemerintahan kolonial yang masih hierarkis. Sebagian alumni sekolah modern kemudian aktif dalam perkumpulan, menuntut perbaikan keadaan, dan mengkritik ketimpangan yang mereka saksikan.","tanya":"Tentukan BENAR atau SALAH pada setiap pernyataan.","analisis":["Benar: kelompok terpelajar merupakan salah satu hasil perluasan pendidikan.","Salah: struktur ketimpangan dan pembatasan kolonial tidak langsung hilang.","Benar: pendidikan turut menyediakan bekal untuk kritik terhadap kolonialisme."],"strategi":["Baca stimulus sebagai hubungan antara kebijakan, aktor, dan akibat.","Hati-hati pada klaim absolut yang melampaui informasi sumber.","Cari perubahan yang tidak sejalan dengan kepentingan pembuat kebijakan."],"rujukan":{"label":"BPCB Sumatera Barat - Eksistensi Guru dan Politik Etis","url":"https://kebudayaan.kemdikbud.go.id/bpcbsumbar/eksistensi-guru-dan-politik-etis/","umum":false},"pernyataan":["Pendidikan membuka peluang munculnya sebagian kaum terpelajar bumiputra.","Politik Etis secara langsung mengakhiri seluruh ketimpangan sosial-politik kolonial.","Dampak pendidikan dapat berbeda dari kepentingan awal penyelenggara kolonial."],"kunci":["B","S","B"],"label":"benar"},{"no":4,"tipe":"PG","judul":"Budi Utomo dan pola perjuangan baru","stimulus":"Budi Utomo berdiri pada 20 Mei 1908 atas prakarsa para pelajar STOVIA, dengan perhatian kuat pada pendidikan dan kemajuan kebudayaan. Organisasi ini sering dikenang sebagai salah satu penanda penting perkembangan gerakan modern di Hindia Belanda.","tanya":"Apa makna historis terpenting berdirinya Budi Utomo dalam perubahan cara memperjuangkan kepentingan masyarakat?","analisis":["Keliru: Budi Utomo bukan gerakan perang bersenjata.","Tepat: organisasi modern menjadi salah satu saluran perjuangan baru.","Keliru: negara merdeka belum berdiri pada 1908.","Keliru: berbagai perkumpulan kedaerahan tetap berkembang.","Keliru: pembatasan pendidikan tidak selesai karena lahirnya satu organisasi."],"strategi":["Bedakan tonggak lahirnya organisasi dengan hasil akhir perjuangan.","Tinjau metode organisasi: pendidikan, rapat, dan program sosial.","Hindari lompatan kronologi dari 1908 langsung ke kemerdekaan."],"rujukan":{"label":"BPCB Banten - Kisah di balik Gedung STOVIA","url":"https://kebudayaan.kemdikbud.go.id/bpcbbanten/kisah-dibalik-gedung-stovia-jakarta-1/","umum":false},"opsi":["Munculnya perang bersenjata nasional yang langsung mengalahkan Belanda.","Menguatnya perjuangan melalui organisasi modern dan program sosial-pendidikan.","Terbentuknya pemerintahan Indonesia merdeka dengan wilayah seluruh Nusantara.","Berakhirnya organisasi yang berdasarkan kedaerahan sejak tahun 1908.","Hilangnya semua batasan akses pendidikan penduduk bumiputra."],"kunci":["B"]},{"no":5,"tipe":"PG","judul":"Dinamika Sarekat Islam","stimulus":"Gerakan yang mula-mula mengorganisasi kepentingan pedagang berkembang menjadi Sarekat Islam dengan basis anggota yang lebih luas. Dalam perjalanannya, persoalan ekonomi, martabat sosial, dan aspirasi politik saling berhubungan.","tanya":"Kesimpulan paling tepat mengenai perkembangan Sarekat Islam adalah ...","analisis":["Keliru: basis awalnya berhubungan dengan kalangan pedagang.","Keliru: persoalan ekonomi dan politik dalam sejarah kerap saling terkait.","Keliru: skala dan cakupan aktivitas Sarekat Islam berubah.","Tepat: jaringan ekonomi berkembang menjadi gerakan masyarakat yang lebih luas.","Keliru: generalisasi mengenai semua organisasi tidak dapat dibuktikan."],"strategi":["Amati urutan \"mula-mula\" dan \"berkembang\".","Identifikasi perluasan basis anggota serta isu yang diperjuangkan.","Jangan menyamakan kasus satu organisasi dengan semua organisasi."],"rujukan":{"label":"BPCB Sumatera Barat - Arti Kebangkitan Nasional","url":"https://kebudayaan.kemdikbud.go.id/bpcbsumbar/arti-kebangkitan-nasional%E2%80%8E/","umum":false},"opsi":["Organisasi ini sejak awal hanya berjuang di lingkungan pejabat kolonial.","Masalah perdagangan tidak pernah berkaitan dengan tuntutan sosial-politik.","Tujuan organisasi tidak mengalami perluasan setelah menjangkau lebih banyak anggota.","Kepentingan ekonomi menjadi salah satu pintu masuk menuju mobilisasi sosial dan politik yang lebih luas.","Semua perkumpulan perdagangan pada masa itu otomatis menjadi partai kemerdekaan."],"kunci":["D"]},{"no":6,"tipe":"BS","judul":"Indische Partij dan gagasan kebangsaan","stimulus":"Indische Partij dibentuk pada 1912 dan menonjol dalam kritik politik terhadap sistem kolonial. Gagasannya menawarkan kerja sama penghuni Hindia dari beragam latar dalam membayangkan masa depan bersama, meskipun ruang geraknya ditekan pemerintah kolonial.","tanya":"Nilailah tiga penafsiran berikut.","analisis":["Benar: gagasan politiknya melampaui kepentingan satu kelompok sempit.","Salah: tujuan dan gagasan inklusifnya tidak sesuai klaim eksklusif tersebut.","Benar: aktivitas politik kritis menghadapi represi pemerintah kolonial."],"strategi":["Pisahkan gagasan organisasi dari respons pemerintah kolonial.","Periksa apakah klaim menggeneralisasi keanggotaan secara berlebihan.","Jelaskan hubungan antara tuntutan politik dan pembatasan kebebasan."],"rujukan":{"label":"BPCB Sumatera Barat - Arti Kebangkitan Nasional","url":"https://kebudayaan.kemdikbud.go.id/bpcbsumbar/arti-kebangkitan-nasional%E2%80%8E/","umum":false},"pernyataan":["Indische Partij menunjukkan bahwa kritik kolonial dapat diarahkan pada tujuan politik lintas kelompok.","Indische Partij hanya memperbolehkan keterlibatan bangsawan dari satu daerah tertentu.","Tekanan kolonial dapat membatasi ruang organisasi politik yang mengusung perubahan."],"kunci":["B","S","B"],"label":"benar"},{"no":7,"tipe":"MC","judul":"Perhimpunan Indonesia dan ruang internasional","stimulus":"Para pelajar Indonesia di Belanda mengembangkan organisasi yang dikenal sebagai Perhimpunan Indonesia. Melalui diskusi, tulisan, dan jaringan luar negeri, mereka memperkenalkan gagasan kemerdekaan dan identitas \"Indonesia\" dalam percakapan politik yang lebih luas.","tanya":"Pilih SEMUA interpretasi yang masuk akal berdasarkan peran Perhimpunan Indonesia.","analisis":["Tepat: isu nasional dibawa ke lingkungan diskusi yang lebih luas.","Tidak tepat: pernyataan tidak didukung fakta dan menghapus perjuangan rakyat.","Tepat: penamaan memiliki makna politik dalam pembentukan identitas.","Tidak tepat: tulisan justru menjadi salah satu sarana perjuangan.","Tepat: jaringan internasional membuka ruang komunikasi politik."],"strategi":["Cari arena perjuangan: dalam negeri, luar negeri, atau keduanya.","Tafsirkan makna politis penamaan sebuah organisasi.","Tolak klaim sebab tunggal untuk proses sejarah yang kompleks."],"rujukan":{"label":"BPCB Sumatera Barat - Arti Kebangkitan Nasional","url":"https://kebudayaan.kemdikbud.go.id/bpcbsumbar/arti-kebangkitan-nasional%E2%80%8E/","umum":false},"opsi":["Mahasiswa di luar negeri dapat mengangkat isu penjajahan ke forum internasional.","Kemerdekaan Indonesia diraih semata-mata melalui bantuan militer pemerintah Belanda.","Pemakaian nama Indonesia ikut menegaskan identitas kebangsaan.","Satu-satunya strategi organisasi adalah melarang semua media cetak.","Jaringan pelajar dapat menghubungkan wacana nasional dengan perkembangan dunia."],"kunci":["A","C","E"]},{"no":8,"tipe":"PG","judul":"PNI dan strategi nonkooperatif","stimulus":"Partai Nasional Indonesia (PNI) didirikan pada 1927. Organisasi ini menekankan kesadaran politik rakyat, kemandirian, dan perjuangan tidak bergantung pada lembaga perwakilan yang dikendalikan pemerintah kolonial.","tanya":"Prinsip yang paling sesuai dengan strategi perjuangan PNI pada periode awal adalah ...","analisis":["Keliru: pengorganisasian justru penting dalam mobilisasi rakyat.","Keliru: kemerdekaan melampaui perubahan jabatan birokrasi.","Tepat: ciri penting nonkooperasi ialah kemandirian perjuangan.","Keliru: tujuan gerakan nasional tidak sebatas restorasi kerajaan.","Keliru: Jepang belum menduduki Indonesia pada 1927."],"strategi":["Kenali istilah nonkooperasi dalam konteks pergerakan nasional.","Bedakan kemandirian gerakan dari sikap pasif.","Periksa kecocokan waktu untuk menyingkirkan anakronisme."],"rujukan":{"label":"BPCB Sumatera Barat - Arti Kebangkitan Nasional","url":"https://kebudayaan.kemdikbud.go.id/bpcbsumbar/arti-kebangkitan-nasional%E2%80%8E/","umum":false},"opsi":["Meminta rakyat menghentikan semua bentuk pengorganisasian.","Menganggap kemerdekaan cukup dicapai melalui pengangkatan pejabat kolonial.","Mengembangkan kekuatan rakyat sendiri dan menolak ketergantungan pada saluran politik kolonial.","Mengutamakan pemulihan kekuasaan kerajaan tradisional di setiap daerah.","Menyerahkan seluruh keputusan politik kepada pemerintah pendudukan Jepang."],"kunci":["C"]},{"no":9,"tipe":"MC","judul":"Kooperasi dan nonkooperasi","stimulus":"Tabel ringkas (disederhanakan): Kelompok X memilih menyuarakan tuntutan melalui forum perwakilan yang tersedia, sekalipun kewenangannya terbatas. Kelompok Y memilih menumbuhkan organisasi mandiri di luar lembaga kolonial. Keduanya berada dalam kondisi pengawasan dan pembatasan politik.","tanya":"Pilih SEMUA evaluasi yang dapat dipertanggungjawabkan secara historis.","analisis":["Tepat: metode dapat berbeda meski cita-cita memiliki irisan.","Tidak tepat: tidak ada bukti eksklusivitas cita-cita kemerdekaan.","Tepat: ruang politik menentukan pilihan taktik.","Tidak tepat: kesimpulan mutlak tidak mengikuti informasi stimulus.","Tepat: evaluasi historis mempertimbangkan banyak variabel."],"strategi":["Pisahkan tujuan, metode, dan hasil perjuangan.","Nilai klaim berdasarkan konteks, bukan label \"kooperatif\" saja.","Waspadai penghakiman tunggal terhadap organisasi yang taktiknya berubah."],"rujukan":{"label":"Kerangka TKA Sejarah - Pusmendik","url":"https://pusmendik.kemdikbud.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"opsi":["Perbedaan taktik tidak otomatis berarti perbedaan tujuan akhir kebangsaan.","Hanya kelompok Y yang mungkin memiliki cita-cita kemerdekaan.","Pilihan strategi perlu dibaca menurut kesempatan dan tekanan politik saat itu.","Keikutsertaan kelompok X di forum kolonial membuktikan mereka selamanya menolak kemerdekaan.","Efektivitas strategi harus dinilai lewat konteks, sasaran, serta hasilnya."],"kunci":["A","C","E"]},{"no":10,"tipe":"PG","judul":"Sumpah Pemuda dan identitas bersama","stimulus":"Kongres Pemuda Kedua di Jakarta pada 27-28 Oktober 1928 mempertemukan wakil berbagai perkumpulan pemuda. Putusannya menegaskan satu tanah air, satu bangsa, serta menjunjung bahasa persatuan Indonesia.","tanya":"Perubahan mendasar apa yang terutama dicerminkan oleh keputusan kongres tersebut?","analisis":["Keliru: persatuan tidak mengharuskan penghapusan budaya daerah.","Tepat: ikrar menghubungkan identitas kedaerahan dengan tujuan kebangsaan.","Keliru: kemerdekaan belum diproklamasikan pada 1928.","Keliru: kegiatan pemuda justru terus berkembang.","Keliru: bahasa persatuan berbeda dari bahasa ibu tiap peserta."],"strategi":["Kenali tiga unsur ikrar: tanah air, bangsa, dan bahasa persatuan.","Bedakan simbol persatuan dari penyeragaman budaya.","Periksa kronologi: ikrar kebangsaan bukan proklamasi negara."],"rujukan":{"label":"Museum Sumpah Pemuda - Sejarah Sumpah Pemuda","url":"https://muspada.kemenbud.go.id/sejarah-sumpah-pemuda/","umum":false},"opsi":["Semua kebudayaan daerah harus dihapus agar identitas nasional terbentuk.","Identitas kebangsaan bersama ditegaskan melampaui asal perkumpulan dan daerah.","Pemerintah Hindia Belanda langsung mengakui negara Indonesia yang berdaulat.","Organisasi pemuda menghentikan segala kegiatan setelah kongres.","Bahasa Indonesia ditetapkan sebagai satu-satunya bahasa ibu seluruh peserta."],"kunci":["B"]},{"no":11,"tipe":"BS","judul":"Bahasa persatuan dan keputusan Kongres 1928","stimulus":"Dalam putusan Kongres Pemuda Kedua, para peserta mengakui tanah air dan bangsa Indonesia serta menjunjung bahasa persatuan, bahasa Indonesia. Rumusan tersebut menjadi landasan komunikasi kebangsaan bagi perkumpulan dengan bahasa daerah yang berbeda-beda.","tanya":"Tentukan BENAR atau SALAH untuk setiap penafsiran.","analisis":["Benar: ketiga aspek menjadi inti putusan.","Salah: menjunjung bahasa persatuan bukan perintah menghapus bahasa daerah.","Benar: fungsi pemersatu membantu hubungan lintas kelompok."],"strategi":["Baca persis nuansa kata \"menjunjung\", bukan menggantinya menjadi \"menghapus\".","Bandingkan identitas nasional dengan identitas daerah.","Jangan menyisipkan aturan yang tidak dinyatakan dalam dokumen."],"rujukan":{"label":"Museum Sumpah Pemuda - Sejarah Sumpah Pemuda","url":"https://muspada.kemenbud.go.id/sejarah-sumpah-pemuda/","umum":false},"pernyataan":["Keputusan kongres menghubungkan persoalan wilayah, bangsa, dan bahasa.","Ikrar bahasa persatuan berarti seluruh bahasa daerah wajib ditinggalkan.","Bahasa persatuan dapat menjadi sarana komunikasi antarperkumpulan yang berlatar daerah berbeda."],"kunci":["B","S","B"],"label":"benar"},{"no":12,"tipe":"MC","judul":"Kongres Perempuan 1928","stimulus":"Kongres Perempuan Indonesia pertama berlangsung di Yogyakarta pada 22-25 Desember 1928 dan menghadirkan berbagai organisasi perempuan. Pertemuan itu memperkuat kerja sama untuk memajukan pendidikan, kedudukan, serta kesejahteraan perempuan dalam masyarakat.","tanya":"Pilih SEMUA simpulan yang sesuai dengan signifikansi kongres tersebut.","analisis":["Tepat: kongres mendorong kolaborasi banyak organisasi.","Tidak tepat: gerakan perempuan beririsan dengan suasana kebangsaan.","Tepat: isu perempuan menjadi agenda publik terorganisasi.","Tidak tepat: kongres melibatkan banyak perkumpulan.","Tepat: pelaku pergerakan lebih beragam daripada satu kelompok saja."],"strategi":["Perhatikan siapa saja aktor yang terlibat dalam sejarah pergerakan.","Hubungkan kemajuan pendidikan dengan perluasan partisipasi publik.","Hindari menyingkirkan gerakan perempuan dari narasi nasional."],"rujukan":{"label":"BPK Wilayah X - Rumah Kebangsaan Dalem Jayadipuran","url":"https://kebudayaan.kemdikbud.go.id/bpkw10/rumah-kebangsaan-dalem-jayadipuran-periode-1900-2014/","umum":false},"opsi":["Organisasi perempuan membangun kerja sama di atas perbedaan perkumpulan.","Gerakan perempuan sepenuhnya terpisah dari perkembangan kesadaran kebangsaan.","Masalah pendidikan dan kedudukan perempuan menjadi bagian dari gerakan sosial modern.","Peserta kongres hanya berasal dari satu organisasi sehingga kerja sama tidak diperlukan.","Pergerakan nasional tidak hanya berlangsung melalui partai dan organisasi pemuda laki-laki."],"kunci":["A","C","E"]},{"no":13,"tipe":"PG","judul":"Propaganda Jepang dan kenyataan pendudukan","stimulus":"Ketika Jepang masuk pada 1942, propaganda \"saudara tua\" dan \"Asia untuk Asia\" digunakan untuk menarik simpati penduduk. Dalam praktiknya, pemerintahan militer mengendalikan kehidupan politik, mengerahkan sumber daya, dan menuntut tenaga kerja untuk kepentingan perang.","tanya":"Penilaian paling tepat atas hubungan propaganda dan kebijakan pendudukan Jepang adalah ...","analisis":["Keliru: propaganda perlu diuji terhadap tindakan nyata.","Tepat: terdapat jarak antara pesan politik dan kebutuhan militer Jepang.","Keliru: kebijakan pendudukan berkaitan erat dengan jalannya perang.","Keliru: kemerdekaan tidak langsung diberikan pada 1942.","Keliru: mobilisasi perang menimbulkan beban berat pada masyarakat."],"strategi":["Bandingkan janji atau slogan dengan kebijakan yang benar-benar dijalankan.","Letakkan pendudukan dalam konteks Perang Asia-Pasifik.","Pilih kesimpulan yang mampu menjelaskan kontradiksi sumber."],"rujukan":{"label":"E-modul Kemdikbud - Sejarah Kelas 8 (masa pendudukan Jepang)","url":"https://emodul.kemdikbud.go.id/C-Sejarah-8/C-Sejarah-8.pdf","umum":false},"opsi":["Slogan pembebasan selalu mencerminkan kenyataan yang dialami penduduk.","Propaganda memperoleh dukungan, tetapi praktik pendudukan memperlihatkan kepentingan perang Jepang.","Pendudukan Jepang sama sekali tidak terkait dengan Perang Pasifik.","Jepang segera memberi rakyat kebebasan membentuk negara berdaulat pada 1942.","Semua kelompok sosial memperoleh manfaat ekonomi yang sama dari mobilisasi perang."],"kunci":["B"]},{"no":14,"tipe":"MC","judul":"Romusha, pangan, dan ekonomi perang","stimulus":"Untuk mendukung perang, militer Jepang mengerahkan tenaga kerja romusha dalam pembangunan fasilitas dan menyelenggarakan penyerahan hasil bumi. Sejumlah keluarga kehilangan anggota produktif serta menghadapi tekanan ekonomi dan kesulitan pangan.","tanya":"Pilih SEMUA penjelasan yang didukung oleh stimulus.","analisis":["Tepat: infrastruktur dan pertahanan membutuhkan banyak pekerja.","Tidak tepat: kesulitan yang tercatat bertentangan dengan klaim perlindungan menyeluruh.","Tepat: hilangnya anggota produktif dan tekanan pangan berdampak luas.","Tidak tepat: stimulus menyebut kesulitan pangan, bukan kelimpahan.","Tepat: kebutuhan perang merupakan faktor penyebab kebijakan mobilisasi."],"strategi":["Tautkan keputusan militer dengan akibat sosial bagi penduduk.","Periksa apakah opsi menambah informasi yang tidak didukung stimulus.","Identifikasi satu sebab yang dapat memunculkan banyak akibat."],"rujukan":{"label":"E-modul Kemdikbud - Sejarah Kelas 8 (masa pendudukan Jepang)","url":"https://emodul.kemdikbud.go.id/C-Sejarah-8/C-Sejarah-8.pdf","umum":false},"opsi":["Pengerahan tenaga kerja berkaitan dengan kebutuhan logistik dan pertahanan perang.","Kebijakan romusha membuktikan bahwa semua pekerja memperoleh perlindungan yang memadai.","Mobilisasi perang dapat mengganggu kehidupan keluarga dan ekonomi setempat.","Penyerahan hasil bumi pasti menyebabkan pangan melimpah bagi semua desa.","Situasi perang membantu menjelaskan meningkatnya tekanan pemerintah pendudukan."],"kunci":["A","C","E"]},{"no":15,"tipe":"BS","judul":"Putera dan Jawa Hokokai","stimulus":"Pusat Tenaga Rakyat (Putera) dibentuk pada 1943 dan melibatkan tokoh nasional seperti Soekarno, Hatta, Ki Hajar Dewantara, dan K.H. Mas Mansur. Jepang kemudian menggantinya dengan Jawa Hokokai pada 1944 untuk mobilisasi masyarakat yang dikendalikan lebih langsung.","tanya":"Tentukan BENAR atau SALAH berdasarkan perbandingan tersebut.","analisis":["Benar: organisasi merupakan alat mobilisasi pemerintahan pendudukan.","Salah: Jawa Hokokai berada dalam kontrol ketat pemerintah militer.","Benar: kepentingan tokoh pergerakan tidak selalu sama dengan kepentingan Jepang."],"strategi":["Bedakan pihak pembentuk organisasi dengan tujuan para tokoh yang terlibat.","Bandingkan perubahan tingkat kontrol organisasi sepanjang waktu.","Hindari menyimpulkan para pelaku memiliki motivasi yang selalu sama."],"rujukan":{"label":"E-modul Kemdikbud - Sejarah Kelas 8 (masa pendudukan Jepang)","url":"https://emodul.kemdikbud.go.id/C-Sejarah-8/C-Sejarah-8.pdf","umum":false},"pernyataan":["Jepang menggunakan organisasi masyarakat untuk mendukung kepentingan perangnya.","Jawa Hokokai sepenuhnya mandiri dan bebas dari kendali pemerintah militer Jepang.","Tokoh nasional dapat berupaya memanfaatkan ruang organisasi meskipun dibentuk Jepang."],"kunci":["B","S","B"],"label":"benar"},{"no":16,"tipe":"BS","judul":"PETA dan perlawanan Blitar","stimulus":"Pembela Tanah Air (PETA) dibentuk oleh Jepang untuk membantu pertahanan. Namun sebagian anggotanya kecewa terhadap perlakuan pemerintah pendudukan. Pada 14 Februari 1945 pecah pemberontakan PETA di Blitar yang dipimpin Supriyadi.","tanya":"Nilailah penafsiran berikut berdasarkan hubungan sebab-akibat.","analisis":["Benar: kemampuan militer dan sikap politik anggota dapat berkembang berbeda.","Salah: tindakan memberontak bertentangan dengan kesimpulan kepatuhan menyeluruh.","Benar: kekecewaan menjadi salah satu pendorong perlawanan."],"strategi":["Lihat paradoks: organisasi yang didirikan penguasa dapat melahirkan oposisi.","Jangan menggeneralisasi sikap semua anggota dari pembentukan organisasi.","Hubungkan pengalaman sosial dengan tindakan kolektif."],"rujukan":{"label":"E-modul Kemdikbud - Sejarah Kelas 8 (masa pendudukan Jepang)","url":"https://emodul.kemdikbud.go.id/C-Sejarah-8/C-Sejarah-8.pdf","umum":false},"pernyataan":["Pelatihan militer dalam organisasi bentukan Jepang tidak selalu menjamin kepatuhan pesertanya.","Pemberontakan Blitar membuktikan bahwa seluruh anggota PETA mendukung kebijakan Jepang.","Ketidakpuasan terhadap kebijakan pendudukan dapat berubah menjadi aksi perlawanan."],"kunci":["B","S","B"],"label":"benar"},{"no":17,"tipe":"PG","judul":"BPUPK dan konteks politik 1945","stimulus":"Pada 1945 posisi Jepang dalam Perang Asia-Pasifik semakin terdesak. Dalam situasi ini, badan persiapan kemerdekaan menjadi tempat tokoh Indonesia mendiskusikan rancangan dasar negara, bentuk negara, dan arah masa depan politik.","tanya":"Penafsiran paling lengkap mengenai badan persiapan kemerdekaan tersebut adalah ...","analisis":["Keliru: pembentukan lembaga terkait kondisi perang yang genting.","Keliru: tokoh Indonesia aktif merumuskan gagasan sendiri.","Keliru: pembahasan persiapan belum sama dengan pengakuan kedaulatan.","Tepat: konteks eksternal dan inisiatif nasional dapat terjadi bersamaan.","Keliru: pengalaman pergerakan sebelumnya justru menjadi latar penting."],"strategi":["Analisis motivasi Jepang sekaligus tujuan aktor Indonesia.","Bedakan persiapan institusional dari kemerdekaan yang telah diproklamasikan.","Jangan memberi jawaban tunggal bagi peristiwa yang melibatkan banyak kepentingan."],"rujukan":{"label":"ANRI - Pameran Arsip Virtual HUT 75","url":"https://anri.go.id/page/pameran-arsip-virtual-hut-75","umum":false},"opsi":["Badan tersebut lahir ketika Jepang sudah tidak memiliki kepentingan militer apa pun.","Seluruh pembicaraan para tokoh Indonesia hanyalah pengulangan perintah Jepang.","Keberadaan badan membuktikan kedaulatan Indonesia telah diakui semua negara.","Kepentingan perang Jepang menciptakan ruang politik yang dipakai tokoh Indonesia untuk merumuskan agenda kebangsaan.","Pembentukan badan menyebabkan perjuangan organisasi nasional sejak 1908 tidak lagi relevan."],"kunci":["D"]},{"no":18,"tipe":"MC","judul":"Menjelang Proklamasi: perbedaan strategi","stimulus":"Setelah Jepang menyatakan menyerah kepada Sekutu pada Agustus 1945, sebagian pemuda mendesak Proklamasi segera dilakukan tanpa ketergantungan pada badan bentukan Jepang. Soekarno-Hatta lebih berhati-hati mengenai cara dan waktu. Ahmad Soebardjo ikut menjembatani perbedaan sikap.","tanya":"Pilih SEMUA simpulan yang tepat mengenai dinamika politik menjelang Proklamasi.","analisis":["Tepat: menyerahnya Jepang mengubah situasi kekuasaan.","Tidak tepat: pemuda justru menuntut tindakan tanpa ketergantungan Jepang.","Tepat: perdebatan menyangkut jalan menuju pernyataan kemerdekaan.","Tidak tepat: keduanya menginginkan kemerdekaan, berbeda dalam strategi.","Tepat: jaminan dan peran Ahmad Soebardjo membantu mencapai penyelesaian."],"strategi":["Pisahkan kesamaan tujuan dari perbedaan cara dan tempo.","Temukan pemicu perubahan keadaan, yakni kekalahan Jepang.","Jangan menyamakan perdebatan strategi dengan pertentangan tujuan akhir."],"rujukan":{"label":"Museum Perumusan Naskah Proklamasi - Kemdikbud","url":"https://kebudayaan.kemdikbud.go.id/sejarah-museum-perumusan-naskah-proklamasi-3/","umum":false},"opsi":["Kekalahan Jepang mempersempit legitimasi kekuasaan pendudukan dan membuka peluang bertindak.","Semua tokoh sepakat bahwa Proklamasi harus menunggu perintah militer Jepang.","Perbedaan pendapat berkaitan dengan waktu, metode, dan kesan ketergantungan politik.","Golongan muda dan golongan tua sama-sama menolak kemerdekaan Indonesia.","Perundingan antartokoh berperan dalam mengatasi kebuntuan strategi."],"kunci":["A","C","E"]},{"no":19,"tipe":"PG","judul":"Kronologi Rengasdengklok hingga Proklamasi","stimulus":"Urutan peristiwa yang perlu diperiksa: (1) Jepang menyerah kepada Sekutu; (2) Soekarno-Hatta dibawa ke Rengasdengklok; (3) naskah Proklamasi disusun di rumah Laksamana Maeda; (4) Proklamasi dibacakan di Pegangsaan Timur 56, Jakarta.","tanya":"Urutan kronologis yang tepat untuk rangkaian peristiwa tersebut adalah ...","analisis":["Keliru: penyerahan Jepang mendahului peristiwa Rengasdengklok.","Keliru: perumusan berlangsung setelah peristiwa Rengasdengklok.","Tepat: menyerahnya Jepang, Rengasdengklok, perumusan, lalu pembacaan.","Keliru: pembacaan Proklamasi dilakukan setelah perumusan.","Keliru: seluruh rangkaian dibalik dari urutan historis."],"strategi":["Tandai tanggal kunci: 15, 16, dan 17 Agustus 1945.","Bedakan peristiwa perumusan dengan pembacaan naskah.","Uji satu titik awal dan akhir sebelum membandingkan opsi."],"rujukan":{"label":"BPNB Jawa Barat - Rumah Sejarah Rengasdengklok","url":"https://kebudayaan.kemdikbud.go.id/bpnbjabar/rumah-sejarah-rengasdengklok-kabupaten-karawang/","umum":false},"opsi":["(2) - (1) - (4) - (3)","(3) - (2) - (1) - (4)","(1) - (2) - (3) - (4)","(1) - (4) - (2) - (3)","(4) - (3) - (2) - (1)"],"kunci":["C"]},{"no":20,"tipe":"BS","judul":"Naskah Proklamasi dan makna kemerdekaan","stimulus":"Arsip menampilkan konsep tulisan tangan naskah Proklamasi dengan koreksi dan versi ketik yang digunakan pada pembacaan 17 Agustus 1945. Pernyataan kemerdekaan disampaikan atas nama bangsa Indonesia. Setelahnya perjuangan mempertahankan kemerdekaan tetap berlangsung.","tanya":"Tentukan BENAR atau SALAH untuk penafsiran berikut.","analisis":["Benar: proklamasi menyatakan kemerdekaan atas nama bangsa Indonesia.","Salah: pengakuan dan penguasaan efektif masih menghadapi perjuangan sesudahnya.","Benar: perbedaan versi dokumen dapat menjadi petunjuk kerja perumusan naskah."],"strategi":["Pisahkan deklarasi kemerdekaan dari proses mempertahankan kedaulatan.","Gunakan perbandingan dokumen sebagai latihan kritik sumber primer.","Hindari menganggap satu peristiwa langsung menyelesaikan seluruh akibat politiknya."],"rujukan":{"label":"ANRI - Naskah Sumber Arsip Seri Presiden RI: Sukarno","url":"https://anri.go.id/download/naskah-sumber-arsip-seri-presiden-ri-sukarno-1586395026","umum":false},"pernyataan":["Proklamasi merupakan pernyataan politik bangsa Indonesia tentang kemerdekaannya.","Sejak pembacaan naskah, seluruh kekuatan asing langsung menerima kedaulatan RI tanpa konflik.","Membandingkan konsep tulisan tangan dengan naskah ketik membantu menelusuri proses perumusan dokumen."],"kunci":["B","S","B"],"label":"benar"}],"4":[{"no":1,"tipe":"PG","judul":"Dari Proklamasi ke pemerintahan RI","stimulus":"Sesudah Proklamasi 17 Agustus 1945, PPKI pada 18 Agustus menetapkan UUD 1945 dan memilih Soekarno serta Mohammad Hatta sebagai presiden dan wakil presiden. Pembentukan lembaga serta perangkat negara berlanjut pada hari-hari berikutnya.","tanya":"Makna historis utama keputusan 18 Agustus 1945 adalah ...","analisis":["Tidak tepat: ancaman militer masih terjadi.","Tepat: konstitusi dan pimpinan dibutuhkan untuk menjalankan negara.","Tidak tepat: diplomasi dengan Belanda berlangsung kemudian.","Tidak tepat: pembangunan kelembagaan masih diperlukan.","Tidak tepat: Proklamasi tetap menjadi pernyataan kemerdekaan."],"strategi":["Pisahkan pernyataan kemerdekaan dan pengorganisasian pemerintahan.","Kenali fungsi konstitusi serta kepemimpinan negara.","Hindari klaim bahwa satu keputusan menyelesaikan semua masalah."],"rujukan":{"label":"Modul Sejarah Indonesia XII - awal kemerdekaan hingga demokrasi liberal","url":"https://repositori.kemendikdasmen.go.id/21960/","umum":false},"opsi":["menjadikan Indonesia otomatis bebas dari seluruh ancaman militer asing.","memberikan dasar konstitusional dan kepemimpinan bagi negara yang baru diproklamasikan.","menyelesaikan seluruh perundingan kedaulatan dengan Belanda.","menghapus kebutuhan pembentukan lembaga negara lainnya.","menggantikan Proklamasi sebagai pernyataan kemerdekaan bangsa."],"kunci":["B"]},{"no":2,"tipe":"BS","judul":"Penataan lembaga dan sistem pemerintahan","stimulus":"Pada Agustus 1945, PPKI membentuk kerangka dasar pemerintahan RI. Pada Oktober 1945, KNIP memperoleh fungsi legislatif sementara; perubahan praktik kabinet berlangsung pada November 1945 ketika sistem parlementer mulai diterapkan dalam situasi revolusi.","tanya":"Tentukan BENAR atau SALAH pada setiap penafsiran berikut.","analisis":["Benar: institusi berkembang melalui beberapa keputusan.","Salah: belum ada pemilu nasional ketika KNIP dibentuk.","Benar: mekanisme kabinet berubah sesuai kebutuhan politik."],"strategi":["Susun urutan keputusan kelembagaan 1945.","Bedakan lembaga sementara dan lembaga hasil pemilu.","Kenali konsep perubahan dalam sistem pemerintahan."],"rujukan":{"label":"Modul Sejarah Indonesia XII - awal kemerdekaan hingga demokrasi liberal","url":"https://repositori.kemendikdasmen.go.id/21960/","umum":false},"pernyataan":["Pembentukan pemerintahan setelah Proklamasi merupakan proses bertahap, bukan satu tindakan tunggal.","KNIP sejak awal dibentuk sebagai parlemen hasil pemilihan umum nasional.","Perubahan praktik kabinet pada 1945 menunjukkan penyesuaian politik pada masa revolusi."],"kunci":["B","S","B"],"label":"benar"},{"no":3,"tipe":"MC","judul":"Uang Republik dan kedaulatan ekonomi","stimulus":"Sesudah merdeka, berbagai uang peninggalan Jepang dan Belanda masih beredar. Pemerintah RI menerbitkan Oeang Republik Indonesia (ORI) pada 1946. Dalam situasi perang dan keterbatasan sarana, beberapa daerah kemudian menerbitkan uang daerah (ORIDA).","tanya":"Pilih SEMUA simpulan yang paling tepat berdasarkan stimulus.","analisis":["Tepat: mata uang terkait fungsi negara dan kedaulatan.","Keliru: penerbitan uang tidak menyelesaikan seluruh masalah ekonomi.","Tepat: ORIDA membantu pemenuhan kebutuhan transaksi lokal.","Keliru: kemerdekaan telah diproklamasikan pada 1945.","Tepat: perang mengganggu komunikasi dan pengedaran uang."],"strategi":["Pahami hubungan simbol negara dan kebutuhan ekonomi nyata.","Periksa klaim yang menyebut akibat serba otomatis.","Tautkan kebijakan daerah dengan hambatan masa revolusi."],"rujukan":{"label":"Mata uang pada awal kemerdekaan - Museum Bank Indonesia","url":"https://www.bi.go.id/id/layanan/museum-bi/Uang-Awal-Kemerdekaan-RI.aspx","umum":false},"opsi":["ORI merupakan bagian dari usaha menegaskan kewenangan ekonomi negara baru.","Penerbitan ORI langsung menghilangkan seluruh masalah inflasi dan kelangkaan barang.","ORIDA menunjukkan adanya respons daerah terhadap kesulitan peredaran uang pada masa revolusi.","Keberadaan beberapa jenis uang membuktikan RI belum pernah memproklamasikan kemerdekaan.","Kebijakan mata uang perlu dipahami dalam konteks perang dan masalah distribusi."],"kunci":["A","C","E"]},{"no":4,"tipe":"PG","judul":"Pertempuran Surabaya 10 November 1945","stimulus":"Kedatangan tentara Sekutu di Surabaya pada 1945 disertai ketegangan dengan pasukan dan rakyat Indonesia. Setelah serangkaian bentrokan, ultimatum Inggris tidak dipenuhi; pertempuran besar pada 10 November berlangsung dengan korban sangat besar.","tanya":"Penilaian paling tepat mengenai makna pertempuran tersebut adalah ...","analisis":["Keliru: perjuangan berlangsung lebih lama di banyak wilayah.","Tepat: perlawanan menjadi simbol kuat tekad kemerdekaan.","Keliru: Proklamasi terjadi dua bulan sebelumnya.","Keliru: perjuangan bersenjata dan diplomasi berjalan berdampingan.","Keliru: revolusi berlangsung di berbagai kota dan daerah."],"strategi":["Lihat makna simbolik pertempuran tanpa membesar-besarkan hasil militernya.","Hubungkan ancaman Sekutu dan respons rakyat.","Hindari pernyataan yang menghapus peristiwa di daerah lain."],"rujukan":{"label":"Pedoman Hari Pahlawan - Sejarah 10 November 1945","url":"https://bpmpkaltara.kemdikbud.go.id/wp-content/uploads/2022/11/Pedoman-Peringatan-Hari-Pahlawan-Tahun-2022.pdf","umum":false},"opsi":["perlawanan bersenjata di Surabaya langsung mengakhiri kehadiran Belanda di seluruh Indonesia.","pertempuran ini menunjukkan kemauan mempertahankan kemerdekaan sekalipun menghadapi kekuatan militer lebih besar.","pertikaian terjadi karena Indonesia belum memproklamasikan kemerdekaan.","pertempuran membuktikan bahwa perjuangan diplomasi tidak pernah terjadi.","Surabaya menjadi satu-satunya daerah yang terlibat dalam revolusi kemerdekaan."],"kunci":["B"]},{"no":5,"tipe":"MC","judul":"Ambarawa dan strategi mempertahankan wilayah","stimulus":"Pada akhir 1945, pasukan TKR serta laskar rakyat berhadapan dengan tentara Sekutu di sekitar Ambarawa. Perlawanan berkembang melalui koordinasi pasukan; tekanan terhadap posisi Sekutu mendorong mundurnya pasukan lawan pada Desember 1945.","tanya":"Pilih SEMUA penjelasan yang didukung stimulus.","analisis":["Tepat: koordinasi memungkinkan gerak pasukan lebih efektif.","Keliru: perjuangan nasional terus berlangsung setelah 1945.","Tepat: lokasi strategis berpengaruh pada operasi militer.","Keliru: Ambarawa berlangsung pada 1945, sebelum KMB.","Tepat: revolusi menyebar ke berbagai wilayah."],"strategi":["Temukan unsur strategi, medan, dan kerja sama.","Periksa tanggal 1945 terhadap hasil KMB 1949.","Bedakan kemenangan di satu wilayah dan hasil perang keseluruhan."],"rujukan":{"label":"Pertempuran Ambarawa - Balai Pelestarian Cagar Budaya","url":"https://kebudayaan.kemdikbud.go.id/bpcbsumbar/pertempuran-ambarawa-cikal-bakal-hari-juang-kartika-infateri/","umum":false},"opsi":["Koordinasi pasukan merupakan salah satu unsur penting perjuangan bersenjata.","Kemenangan lokal berarti semua konflik bersenjata di Indonesia langsung berakhir.","Kondisi wilayah dan posisi strategis dapat memengaruhi jalannya pertempuran.","Pertempuran Ambarawa terjadi sesudah Belanda mengakui kedaulatan RIS pada 1949.","Peristiwa ini memperlihatkan bahwa pertahanan republik juga berlangsung di luar Jakarta."],"kunci":["A","C","E"]},{"no":6,"tipe":"BS","judul":"PDRI ketika ibu kota diserang","stimulus":"Agresi Militer Belanda II pada Desember 1948 menyerang Yogyakarta serta menahan sejumlah pimpinan Republik. Di Sumatra dibentuk Pemerintahan Darurat Republik Indonesia (PDRI) di bawah Sjafruddin Prawiranegara untuk menjaga kesinambungan pemerintahan.","tanya":"Tentukan BENAR atau SALAH setiap kesimpulan.","analisis":["Benar: pemerintahan darurat menjaga fungsi republik.","Salah: perlawanan dan diplomasi terus berjalan, republik tidak berhenti begitu saja.","Benar: jaringan pemerintah serta perjuangan melampaui ibu kota."],"strategi":["Pisahkan pendudukan kota dari kelangsungan lembaga negara.","Amati pembentukan pemerintahan alternatif dalam masa krisis.","Waspadai kata mutlak seperti 'selamanya'."],"rujukan":{"label":"Modul Sejarah - Revolusi Indonesia, Kemendikbud","url":"https://repositori.kemendikdasmen.go.id/21960/","umum":false},"pernyataan":["PDRI menunjukkan usaha menjaga kelangsungan pemerintahan ketika pimpinan pusat ditawan.","Penahanan presiden membuktikan bahwa Republik secara hukum dan politik langsung lenyap selamanya.","Peristiwa ini memperlihatkan bahwa keberlangsungan negara tidak hanya bergantung pada penguasaan ibu kota."],"kunci":["B","S","B"],"label":"benar"},{"no":7,"tipe":"PG","judul":"Gerilya dan daya tahan Republik","stimulus":"Sesudah serangan Belanda terhadap Yogyakarta pada akhir 1948, pasukan Republik melanjutkan perlawanan dengan pola gerilya. Mobilitas dan dukungan masyarakat membuat perjuangan tidak berhenti meskipun sejumlah pusat kota dikuasai lawan.","tanya":"Kesimpulan paling tepat tentang peran perang gerilya adalah ...","analisis":["Keliru: dukungan masyarakat penting dalam gerilya.","Tepat: perlawanan tetap berlangsung dengan strategi bergerak.","Keliru: tujuan utamanya mempertahankan kemerdekaan.","Keliru: keberhasilan gerilya tidak selalu berupa kemenangan pertempuran langsung.","Keliru: perang gerilya terjadi jauh sebelum 1955."],"strategi":["Baca hubungan antara kondisi perang dan pemilihan taktik.","Nilai strategi dari kemampuannya mempertahankan perlawanan.","Gunakan kronologi untuk menolak opsi anakronistis."],"rujukan":{"label":"Modul Sejarah - Revolusi Indonesia, Kemendikbud","url":"https://repositori.kemendikdasmen.go.id/21960/","umum":false},"opsi":["gerilya bertujuan membuktikan tidak perlunya hubungan dengan rakyat.","gerilya menjaga kemampuan perlawanan di tengah keunggulan persenjataan lawan.","gerilya dilakukan semata-mata untuk menggantikan pemerintah dengan kekuasaan militer.","gerilya selalu menghasilkan kemenangan terbuka dalam satu hari.","gerilya baru mulai sesudah Konferensi Asia-Afrika 1955."],"kunci":["B"]},{"no":8,"tipe":"MC","judul":"Linggarjati dan batas pengakuan","stimulus":"Perundingan Linggarjati pada November 1946 mempertemukan delegasi RI dan Belanda. Salah satu pokok kesepakatan adalah pengakuan de facto Belanda terhadap wilayah RI di Jawa, Madura, dan Sumatra, disertai rencana pembentukan Republik Indonesia Serikat dan Uni Indonesia-Belanda.","tanya":"Pilih SEMUA evaluasi yang sesuai.","analisis":["Tepat: jalur perundingan melengkapi perjuangan bersenjata.","Keliru: pengakuan de facto terbatas bukan pengakuan kedaulatan penuh.","Tepat: cakupan Jawa, Madura, Sumatra menunjukkan batas pengakuan.","Keliru: pembentukan negara serikat justru menjadi bagian rencana.","Tepat: diplomasi menghadapi berbagai kepentingan dan tekanan."],"strategi":["Perbedakan pengakuan de facto dan kedaulatan penuh.","Perhatikan wilayah yang disebut eksplisit dalam kesepakatan.","Evaluasi hasil perundingan sebagai kompromi, bukan solusi final."],"rujukan":{"label":"Linggarjati dan diplomasi RI - Kementerian Pendidikan","url":"https://kebudayaan.kemdikbud.go.id/bpnbjabar/cagar-budaya-gedung-naskah-linggarjati/","umum":false},"opsi":["Diplomasi menyediakan ruang pengakuan politik ketika konflik bersenjata masih berlangsung.","Hasil Linggarjati merupakan pengakuan kedaulatan penuh RI atas seluruh bekas Hindia Belanda.","Ketentuan wilayah pengakuan menunjukkan adanya batas yang dapat menimbulkan perdebatan.","Isi persetujuan sama sekali tidak berkaitan dengan gagasan bentuk negara.","Dokumen perundingan perlu dibaca dalam konteks kompromi dan ketimpangan posisi tawar."],"kunci":["A","C","E"]},{"no":9,"tipe":"PG","judul":"Renville dan perubahan posisi Republik","stimulus":"Sesudah Agresi Militer Belanda I pada 1947, perundingan berlangsung di kapal USS Renville dan menghasilkan persetujuan pada Januari 1948. Garis demarkasi dalam perjanjian turut mempersempit wilayah yang berada di bawah kendali efektif Republik.","tanya":"Dampak yang paling tepat dikaitkan dengan persetujuan Renville adalah ...","analisis":["Keliru: posisi teritorial RI justru semakin terdesak.","Tepat: hasil Renville memperberat situasi pertahanan dan politik RI.","Keliru: itu peristiwa lain dan lebih awal.","Keliru: peristiwa moneter terjadi kemudian.","Keliru: peristiwa ketatanegaraan terjadi tahun 1959."],"strategi":["Temukan sebab-akibat pasca agresi, bukan sekadar nama perjanjian.","Bedakan pengakuan formal dari kontrol wilayah di lapangan.","Coret pilihan yang mencampur periode sejarah."],"rujukan":{"label":"Modul Sejarah - Revolusi Indonesia, Kemendikbud","url":"https://repositori.kemendikdasmen.go.id/21960/","umum":false},"opsi":["menguatnya kedudukan wilayah RI karena seluruh daerah pendudukan Belanda diserahkan seketika.","meningkatnya kesulitan politik dan militer Republik akibat pembatasan wilayah serta perubahan posisi pasukan.","berakhirnya penjajahan Jepang pada 1942.","terbentuknya Bank Indonesia sebagai bank sentral pada 1953.","dibubarkannya Konstituante lewat Dekrit Presiden 1959."],"kunci":["B"]},{"no":10,"tipe":"BS","judul":"Roem-Royen dan kembalinya pemerintah RI","stimulus":"Perundingan Roem-Royen mencapai persetujuan pada Mei 1949 sesudah tekanan internasional terhadap konflik Indonesia-Belanda meningkat. Kesepakatan membuka jalan untuk pemulihan pemerintahan RI di Yogyakarta dan menuju perundingan lebih lanjut mengenai kedaulatan.","tanya":"Nilailah setiap pernyataan berikut sebagai BENAR atau SALAH.","analisis":["Benar: persetujuan menyiapkan pemulihan pemerintahan dan kelanjutan dialog.","Salah: persoalan-persoalan, termasuk Irian Barat, belum selesai.","Benar: faktor eksternal turut mengubah ruang negosiasi."],"strategi":["Susun rantai peristiwa Agresi II - Roem-Royen - KMB.","Bedakan hasil antara dan penyelesaian akhir.","Periksa peran tekanan internasional secara proporsional."],"rujukan":{"label":"Modul Sejarah - Revolusi Indonesia, Kemendikbud","url":"https://repositori.kemendikdasmen.go.id/21960/","umum":false},"pernyataan":["Roem-Royen merupakan tahapan diplomasi menuju penyelesaian konflik kedaulatan.","Perundingan ini mengakhiri seluruh persoalan hubungan Indonesia-Belanda untuk selamanya.","Konteks tekanan internasional membantu menjelaskan mengapa para pihak kembali berunding."],"kunci":["B","S","B"],"label":"benar"},{"no":11,"tipe":"PG","judul":"KMB dan penyerahan kedaulatan 1949","stimulus":"Konferensi Meja Bundar (KMB) berlangsung di Den Haag pada 23 Agustus-2 November 1949. Hasilnya menjadi dasar penyerahan kedaulatan oleh Belanda pada 27 Desember 1949 kepada Republik Indonesia Serikat; persoalan Irian Barat belum tuntas diselesaikan.","tanya":"Analisis terbaik atas hasil KMB adalah ...","analisis":["Keliru: Irian Barat tetap menjadi sengketa.","Keliru: pengalihan kedaulatan merupakan capaian utama.","Tepat: ada kemajuan besar sekaligus perkara yang belum selesai.","Keliru: Jepang tidak menjadi pihak penguasa pada 1949.","Keliru: KMB berlangsung empat tahun sesudah Proklamasi."],"strategi":["Catat tanggal, pihak yang terlibat, dan bentuk negara penerima kedaulatan.","Hindari menyamakan kemajuan diplomatik dengan tuntasnya semua sengketa.","Bedakan RI 1945 dan RIS 1949 sebagai bentuk ketatanegaraan."],"rujukan":{"label":"Modul Sejarah - Revolusi Indonesia, Kemendikbud","url":"https://repositori.kemendikdasmen.go.id/21960/","umum":false},"opsi":["KMB menyelesaikan semua sengketa bilateral, termasuk Irian Barat, secara seketika.","KMB tidak berhubungan dengan pengakuan kedaulatan Indonesia.","KMB menjadi tonggak penting pengalihan kedaulatan, tetapi menyisakan persoalan politik dan wilayah.","KMB mengubah Indonesia menjadi negara penjajahan Jepang untuk kedua kalinya.","KMB berlangsung sebelum Proklamasi Kemerdekaan."],"kunci":["C"]},{"no":12,"tipe":"MC","judul":"Dari RIS kembali ke NKRI 1950","stimulus":"Setelah penyerahan kedaulatan Desember 1949, Indonesia berbentuk Republik Indonesia Serikat (RIS). Desakan untuk menyatukan negara bagian menguat; pada 17 Agustus 1950 Indonesia kembali ke bentuk negara kesatuan berdasarkan UUD Sementara 1950.","tanya":"Pilih SEMUA kesimpulan yang didukung kronologi tersebut.","analisis":["Tepat: bentuk federal 1949 berganti kesatuan 1950.","Keliru: 1950 adalah awal kembali ke NKRI, bukan awal RIS.","Tepat: aspirasi persatuan mendorong perubahan bentuk negara.","Keliru: praktik parlementer berlangsung pada masa UUDS 1950.","Tepat: UUDS menandai dasar hukum bentuk negara baru."],"strategi":["Buat urutan RIS 1949 - NKRI dan UUDS 1950.","Pisahkan bentuk negara dengan sistem kabinet.","Perhatikan hubungan tuntutan politik dan perubahan konstitusi."],"rujukan":{"label":"Modul Sejarah Indonesia XII - awal kemerdekaan hingga demokrasi liberal","url":"https://repositori.kemendikdasmen.go.id/21960/","umum":false},"opsi":["Bentuk negara Indonesia mengalami perubahan dalam waktu relatif singkat setelah KMB.","RIS dibentuk untuk pertama kalinya pada 17 Agustus 1950.","Dorongan politik menuju persatuan berkaitan dengan perubahan dari federal menjadi kesatuan.","Kembalinya NKRI berarti kehidupan parlementer otomatis berakhir pada 1950.","Perubahan konstitusi menjadi bagian penting proses transisi kelembagaan."],"kunci":["A","C","E"]},{"no":13,"tipe":"BS","judul":"Kedaulatan dan persoalan Irian Barat","stimulus":"Penyerahan kedaulatan pada 1949 dan kembalinya negara kesatuan pada 1950 tidak dengan sendirinya menyelesaikan sengketa Irian Barat. Indonesia terus memperjuangkannya melalui beragam upaya dalam periode berikutnya.","tanya":"Tentukan BENAR atau SALAH pada pernyataan ini.","analisis":["Benar: proses diplomasi 1949 tidak menuntaskan sengketa wilayah ini.","Salah: sengketa Irian Barat berlanjut setelah 1950.","Benar: perubahan status wilayah memerlukan upaya lanjutan."],"strategi":["Pisahkan kedaulatan negara secara umum dari sengketa wilayah khusus.","Perhatikan keberlanjutan persoalan lintas periode.","Jangan menganggap perubahan konstitusi menyelesaikan isu eksternal."],"rujukan":{"label":"Modul Sejarah Indonesia XII - awal kemerdekaan hingga demokrasi liberal","url":"https://repositori.kemendikdasmen.go.id/21960/","umum":false},"pernyataan":["Pengakuan kedaulatan dapat terjadi sementara sengketa wilayah tertentu tetap berlangsung.","Berubahnya RIS menjadi NKRI pada 1950 membuat Irian Barat otomatis diserahkan saat itu juga.","Perjuangan mempertahankan dan melengkapi kedaulatan berlangsung melalui beberapa tahap sejarah."],"kunci":["B","S","B"],"label":"benar"},{"no":14,"tipe":"PG","judul":"Pergantian kabinet dan stabilitas politik","stimulus":"Pada masa UUDS 1950, kabinet dibentuk dalam sistem parlementer dan bertanggung jawab kepada parlemen. Koalisi antarpartai dapat berubah, sehingga pergantian kabinet berlangsung relatif sering meskipun aktivitas partai dan perdebatan publik cukup dinamis.","tanya":"Hubungan sebab-akibat paling tepat tentang situasi politik tersebut adalah ...","analisis":["Tepat: pergantian kabinet dapat mengganggu kesinambungan kebijakan.","Keliru: sistem Indonesia tetap republik.","Keliru: Pemilu 1955 justru diselenggarakan pada era parlementer.","Keliru: kabinet bertanggung jawab secara politik kepada parlemen.","Keliru: koalisi dan perdebatan menunjukkan perbedaan kepentingan."],"strategi":["Kenali ciri pemerintahan parlementer dan konsekuensi koalisi.","Pisahkan dinamika demokrasi dari kesinambungan program.","Gunakan Pemilu 1955 untuk menguji klaim yang terlalu mutlak."],"rujukan":{"label":"Modul Sejarah Indonesia XII - awal kemerdekaan hingga demokrasi liberal","url":"https://repositori.kemendikdasmen.go.id/21960/","umum":false},"opsi":["koalisi yang rapuh dapat melemahkan keberlanjutan program pemerintahan.","sering bergantinya kabinet membuktikan Indonesia saat itu dipimpin raja.","pemilihan umum tidak mungkin diadakan dalam sistem parlementer.","kabinet bertanggung jawab kepada komandan militer, bukan parlemen.","seluruh partai selalu sepakat dalam semua keputusan politik."],"kunci":["A"]},{"no":15,"tipe":"MC","judul":"Pemilu 1955: representasi dan tantangan","stimulus":"Indonesia menyelenggarakan dua pemungutan suara pada 1955: pemilihan DPR tanggal 29 September dan Konstituante tanggal 15 Desember. Banyak partai dan kelompok mengikuti pemilu; hasilnya tidak melahirkan satu kekuatan yang mendominasi seluruh kursi.","tanya":"Pilih SEMUA penafsiran sejarah yang tepat.","analisis":["Tepat: partisipasi plural tampak dalam pemilu.","Keliru: tanggal pemilihan DPR dan Konstituante berbeda.","Tepat: banyak kekuatan partai menyulitkan penyusunan koalisi kuat.","Keliru: justru terdapat kompetisi antarpeserta.","Tepat: satu pemilu untuk DPR, satu untuk Konstituante."],"strategi":["Uji tanggal 29 September dan 15 Desember secara teliti.","Bedakan keberhasilan prosedur pemilu dan stabilitas kabinet.","Hubungkan sebaran kekuatan partai dengan dinamika koalisi."],"rujukan":{"label":"Sejarah Pemilu 1955 - KPU Republik Indonesia","url":"https://www.kpu.go.id/page/read/8/pemilu-1955","umum":false},"opsi":["Pemilu 1955 mencerminkan partisipasi dan keberagaman pilihan politik.","Pemilu DPR dan Konstituante dilakukan pada hari yang sama.","Fragmentasi kekuatan politik dapat menyulitkan terbentuknya kabinet koalisi yang stabil.","Pemilu 1955 membuktikan bahwa tidak ada kompetisi partai politik.","Dua pemilihan itu memiliki tujuan kelembagaan yang berbeda."],"kunci":["A","C","E"]},{"no":16,"tipe":"BS","judul":"Nasionalisasi De Javasche Bank","stimulus":"Pemerintah Indonesia mengambil alih De Javasche Bank melalui proses nasionalisasi. Undang-Undang No. 11 Tahun 1953 mengatur Bank Indonesia; sejak 1 Juli 1953 Bank Indonesia berdiri resmi sebagai bank sentral RI.","tanya":"Tentukan BENAR atau SALAH untuk setiap analisis.","analisis":["Benar: otoritas bank sentral menjadi bagian fungsi negara berdaulat.","Salah: BI baru resmi berdiri pada 1 Juli 1953.","Benar: kedaulatan ekonomi membutuhkan lembaga nasional."],"strategi":["Kaitkan lembaga bank sentral dengan fungsi kedaulatan.","Periksa tanggal 1 Juli 1953, bukan 17 Agustus 1945.","Pahami kesinambungan antara kemerdekaan politik dan reformasi ekonomi."],"rujukan":{"label":"Sejarah Bank Indonesia - Bank Indonesia","url":"https://www.bi.go.id/id/tentang-bi/sejarah-bi/default.aspx","umum":false},"pernyataan":["Pembentukan Bank Indonesia memperkuat kemandirian pengelolaan moneter nasional.","Bank Indonesia resmi berdiri tahun 1945, tepat pada hari Proklamasi.","Perubahan kelembagaan keuangan dapat dibaca sebagai kelanjutan usaha mengisi kemerdekaan ekonomi."],"kunci":["B","S","B"],"label":"benar"},{"no":17,"tipe":"PG","judul":"Kebijakan Gunting Sjafruddin","stimulus":"Pada Maret 1950, Menteri Keuangan Sjafruddin Prawiranegara menjalankan kebijakan yang dikenal sebagai Gunting Sjafruddin. Uang kertas tertentu pecahan besar dipotong; bagian kiri tetap berlaku dengan nilai separuh, sementara bagian kanan dikaitkan dengan pinjaman pemerintah.","tanya":"Tujuan pokok kebijakan tersebut dalam konteks ekonomi awal kemerdekaan adalah ...","analisis":["Keliru: kebijakan justru bertujuan menata uang beredar.","Tepat: pemotongan nilai dan pinjaman ditujukan pada masalah keuangan.","Keliru: transaksi antardaerah tetap diperlukan.","Keliru: kebijakan moneter tidak membatalkan kemerdekaan.","Keliru: isu keuangan berbeda dari agenda pemilu lima tahun kemudian."],"strategi":["Identifikasi masalah yang hendak diatasi kebijakan moneter.","Bedakan nilai nominal uang dan pembiayaan pemerintah.","Singkirkan opsi yang tidak mempunyai hubungan ekonomi langsung."],"rujukan":{"label":"Gunting Sjafruddin - Museum Bank Indonesia","url":"https://www.bi.go.id/id/layanan/museum-bi/Uang-Awal-Kemerdekaan-RI.aspx","umum":false},"opsi":["menambah jumlah uang beredar tanpa batas.","mengendalikan tekanan moneter dan menghimpun pembiayaan negara.","menghapus seluruh kebutuhan perdagangan antardaerah.","mengubah Indonesia menjadi negara jajahan Belanda kembali.","menggantikan penyelenggaraan Pemilu DPR 1955."],"kunci":["B"]},{"no":18,"tipe":"BS","judul":"Dekrit Presiden 5 Juli 1959","stimulus":"Konstituante hasil Pemilu 1955 menghadapi kebuntuan dalam menetapkan undang-undang dasar baru. Pada 5 Juli 1959, Presiden Soekarno mengeluarkan dekrit yang antara lain membubarkan Konstituante dan memberlakukan kembali UUD 1945.","tanya":"Tentukan BENAR atau SALAH terhadap tiga kesimpulan.","analisis":["Benar: kebuntuan Konstituante menjadi salah satu konteks dekrit.","Salah: RIS terbentuk pada 1949, satu dekade lebih awal.","Benar: dasar konstitusional negara berubah dari UUDS 1950."],"strategi":["Hubungkan sebab institusional dan kebijakan dekrit.","Bedakan tanggal pembentukan RIS dengan akhir sistem parlementer.","Catat perubahan UUDS 1950 ke UUD 1945."],"rujukan":{"label":"Modul SMA - Politik dan ekonomi Demokrasi Terpimpin","url":"https://repositori.kemendikdasmen.go.id/21941/1/XII_Sejarah-Indonesia_KD-3.4_final.pdf","umum":false},"pernyataan":["Dekrit 5 Juli 1959 berkaitan dengan kebuntuan proses penyusunan konstitusi.","Dekrit tersebut menandai lahirnya Republik Indonesia Serikat pada 1949.","Kembalinya UUD 1945 merupakan perubahan penting dalam tata politik saat itu."],"kunci":["B","S","B"],"label":"benar"},{"no":19,"tipe":"MC","judul":"Konsentrasi kekuasaan pada Demokrasi Terpimpin","stimulus":"Dalam Demokrasi Terpimpin, kedudukan Presiden Soekarno menguat. Pemerintah menerapkan kebijakan politik seperti Manipol-USDEK dan membatasi ruang gerak sejumlah partai serta media. Dinamika politik melibatkan persaingan dan kerja sama antar-kekuatan besar.","tanya":"Pilih SEMUA evaluasi historis yang dapat dipertanggungjawabkan.","analisis":["Tepat: presiden memiliki peran politik semakin dominan.","Keliru: sejumlah media dan partai justru mengalami pembatasan.","Tepat: evaluasi sejarah membandingkan gagasan dengan pelaksanaan.","Keliru: ketegangan politik tetap berlangsung.","Tepat: perubahan institusi membantu menerangkan konsentrasi kekuasaan."],"strategi":["Bedakan slogan politik dan praktik kekuasaan.","Periksa kebijakan terhadap pers, partai, dan lembaga negara.","Nilai keseimbangan institusi, jangan hanya menghafal satu tokoh."],"rujukan":{"label":"Modul SMA - Politik dan ekonomi Demokrasi Terpimpin","url":"https://repositori.kemendikdasmen.go.id/21941/1/XII_Sejarah-Indonesia_KD-3.4_final.pdf","umum":false},"opsi":["Terdapat kecenderungan pemusatan kekuasaan politik pada presiden.","Masa ini dicirikan kebebasan pers tanpa pembatasan apa pun.","Untuk menilai kebijakan, perlu membedakan tujuan resmi dari dampak nyata bagi masyarakat.","Seluruh konflik kepentingan politik otomatis hilang karena gagasan persatuan.","Perubahan hubungan antarlembaga dan partai penting untuk memahami periode ini."],"kunci":["A","C","E"]},{"no":20,"tipe":"PG","judul":"Deklarasi Ekonomi 1963 dan realitasnya","stimulus":"Pada 1963 pemerintah memperkenalkan Deklarasi Ekonomi (Dekon) dengan cita-cita ekonomi nasional yang lebih mandiri. Namun pada tahun-tahun akhir Demokrasi Terpimpin, tekanan harga, pembiayaan negara, dan beban berbagai agenda politik-ekonomi tetap berat.","tanya":"Penilaian paling masuk akal berdasarkan perbandingan tujuan dan kenyataan kebijakan adalah ...","analisis":["Keliru: pernyataan kebijakan tidak menjamin hasil instan.","Tepat: evaluasi membandingkan tujuan, pelaksanaan, dan dampak nyata.","Keliru: sejumlah masalah ekonomi masih membebani masyarakat.","Keliru: pilihan anggaran dan kebijakan berpengaruh terhadap ekonomi.","Keliru: slogan bukan indikator tunggal kondisi ekonomi."],"strategi":["Pisahkan niat kebijakan dan hasil nyata.","Hubungkan pembiayaan, produksi, dan tekanan harga.","Nilai kesejahteraan warga sebagai aspek penting evaluasi."],"rujukan":{"label":"Modul belajar mandiri IPS Sejarah - Demokrasi Terpimpin","url":"https://repositori.kemendikdasmen.go.id/22701/1/MODUL%20BELAJAR%20MANDIRI_IPS-SEJARAH_2021.pdf","umum":false},"opsi":["deklarasi politik ekonomi selalu langsung membuat harga turun.","cita-cita kemandirian perlu diukur bersama kemampuan pelaksanaan, sumber daya, dan dampaknya terhadap kehidupan rakyat.","banyaknya agenda pemerintah membuktikan bahwa masalah ekonomi telah hilang.","situasi 1963 tidak memiliki hubungan dengan pengeluaran dan arah kebijakan negara.","keberhasilan ekonomi cukup diukur dari banyaknya slogan yang disampaikan."],"kunci":["B"]}],"5":[{"no":1,"tipe":"PG","judul":"Supersemar dan kritik sumber sejarah","stimulus":"ANRI menyebut Surat Perintah Sebelas Maret 1966 (Supersemar) sebagai arsip penting, sementara persoalan naskah aslinya masih menjadi perhatian penelitian. Dokumen ini sering digunakan dalam penjelasan perubahan kekuasaan pada 1966–1967.","tanya":"Langkah sejarawan yang paling tepat untuk menilai berbagai versi penafsiran Supersemar ialah ...","analisis":["Popularitas sebuah salinan tidak membuktikan autentisitasnya.","Tepat: kritik sumber eksternal dan internal perlu disertai pemeriksaan konteks.","Keliru: keterbatasan sumber mendorong kehati-hatian, bukan penghapusan kajian.","Keliru: satu buku tidak cukup untuk masalah arsip yang kompleks.","Keliru: kesaksian tunggal perlu diuji silang dengan bukti lain."],"strategi":["Cari persoalan utama: otentisitas, isi, dan konteks dokumen.","Utamakan verifikasi silang daripada asumsi politik.","Hindari jawaban yang mengklaim kepastian tanpa bukti."],"rujukan":{"label":"Kajian dan arsip Supersemar - Arsip Nasional RI","url":"https://anri.go.id/publikasi/berita/menilik-sejarah-dan-arsip-supersemar-melalui-tayangan-top-secret","umum":false},"opsi":["menganggap salinan yang paling populer pasti merupakan naskah asli.","membandingkan salinan, arsip terkait, kesaksian, konteks politik, serta asal-usul setiap sumber.","menghapus semua pembahasan peristiwa karena naskah aslinya belum ditemukan.","menggunakan satu buku pelajaran tanpa memeriksa dokumen lain.","memastikan isi dokumen hanya berdasarkan ingatan satu narasumber."],"kunci":["B"]},{"no":2,"tipe":"MC","judul":"Kronologi peralihan pemerintahan","stimulus":"Ringkasan kronologi: Supersemar terbit pada 11 Maret 1966; MPRS menetapkan Soeharto sebagai pejabat presiden pada Maret 1967; Soeharto kemudian ditetapkan sebagai presiden pada 1968. Pergantian kekuasaan berlangsung melalui serangkaian keputusan politik dan kelembagaan.","tanya":"Pilih SEMUA simpulan yang didukung kronologi tersebut.","analisis":["Tepat: rangkaian peristiwa membentang dari 1966 hingga 1968.","Tidak tepat: tanggal 11 Maret 1966 terkait Supersemar, bukan penetapan presiden.","Tepat: dua status konstitusional itu berbeda.","Tidak tepat: klaim serba selesai bertentangan dengan kronologi.","Tepat: analisis kronologis menghindari penyederhanaan satu peristiwa."],"strategi":["Susun lini masa sebelum menilai simpulan.","Bedakan status pejabat presiden dan presiden.","Singkirkan pilihan yang memampatkan proses bertahun-tahun menjadi satu tanggal."],"rujukan":{"label":"Sukarno ke Soeharto - Direktorat Kebudayaan (topik terkait)","url":"https://kebudayaan.kemdikbud.go.id/dpk/direktorat-pelindungan-kebudayaan/page/79/","umum":false},"opsi":["Peralihan kepemimpinan berlangsung melalui lebih dari satu tahap.","Soeharto sudah ditetapkan sebagai presiden pada 11 Maret 1966.","Penetapan sebagai pejabat presiden berbeda dari pengangkatan sebagai presiden.","Semua perubahan lembaga negara pasti selesai tepat pada hari Supersemar diterbitkan.","Urutan keputusan membantu memahami proses transisi kekuasaan."],"kunci":["A","C","E"]},{"no":3,"tipe":"BS","judul":"Perubahan dan keberlanjutan negara","stimulus":"Pergantian kepemimpinan 1966–1968 mengubah orientasi banyak kebijakan negara. Namun, perubahan pemerintahan tidak berarti seluruh lembaga, peraturan, atau kehidupan masyarakat langsung berganti pada waktu yang sama.","tanya":"Tentukan BENAR atau SALAH untuk setiap pernyataan.","analisis":["Benar: lembaga dapat berlanjut sambil mengalami penyesuaian.","Salah: dampak politik pada kehidupan masyarakat tidak selalu serentak.","Benar: dua konsep tersebut menjelaskan aspek yang berubah dan bertahan."],"strategi":["Cari kata petunjuk seperti \"namun\" dan \"tidak seluruh\".","Bedakan peristiwa politik dengan proses sosial yang lebih lambat.","Jangan menganggap pergantian pemimpin mengubah semua hal sekaligus."],"rujukan":{"label":"Matriks dan karakter soal TKA Sejarah - Pusmendik","url":"https://pusmendik.kemdikbud.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"pernyataan":["Transisi politik dapat membawa perubahan kebijakan tanpa menghapus semua lembaga negara.","Perubahan presiden berarti otomatis seluruh kondisi sosial ekonomi berubah seketika.","Konsep perubahan dan keberlanjutan membantu membaca transisi 1966–1968."],"kunci":["B","S","B"],"label":"benar"},{"no":4,"tipe":"PG","judul":"Pemilu 1971 dan konsolidasi Orde Baru","stimulus":"Pemilu 1971 merupakan pemilu pertama pada masa Orde Baru. Pemilu ini diselenggarakan untuk memilih wakil rakyat, tetapi berlangsung dalam tata politik yang memperlihatkan penguatan pengaruh pemerintah dan Golkar.","tanya":"Kesimpulan historis yang paling tepat ialah ...","analisis":["Keliru: prosedur pemilu perlu dibedakan dari kualitas kompetisinya.","Keliru: pemilu masa Orde Baru jelas diselenggarakan.","Tepat: keberadaan pemilu dan dominasi politik dapat terjadi bersamaan.","Keliru: pemilu tidak mengakhiri seluruh lembaga negara.","Keliru: akses politik tidak otomatis setara."],"strategi":["Pisahkan keberadaan mekanisme pemilu dari kondisi persaingannya.","Perhatikan aktor yang memiliki pengaruh dominan.","Singkirkan generalisasi seperti \"semua\" dan \"identik\"."],"rujukan":{"label":"Sejarah penyelenggaraan pemilu - KPU","url":"https://kab-tobasamosir.kpu.go.id/page/read/sejarah-penyelenggaraan-pemilu-dan-pilkada","umum":false},"opsi":["adanya pemilu saja sudah cukup membuktikan persaingan politik berlangsung setara.","pemilu tidak pernah diselenggarakan pada masa Orde Baru.","pemilu dapat berlangsung bersamaan dengan ketimpangan pengaruh antarkekuatan politik.","hasil pemilu 1971 langsung menghapus semua lembaga pemerintahan.","setiap kelompok politik memiliki sumber daya dan akses yang identik."],"kunci":["C"]},{"no":5,"tipe":"MC","judul":"Penyederhanaan kontestan politik","stimulus":"Setelah penyederhanaan partai politik pada 1973, pemilu 1977–1997 diikuti tiga kontestan: Golkar, PPP, dan PDI. Golkar berulang kali meraih kemenangan besar. Pemerintah menonjolkan stabilitas, tetapi kompetisi partai menjadi lebih terbatas.","tanya":"Pilih SEMUA penilaian yang dapat dipertanggungjawabkan.","analisis":["Tepat: struktur kontestan menjadi lebih terbatas.","Tidak tepat: periode pemilu berbeda dalam jumlah peserta.","Tepat: evaluasi sejarah menimbang tujuan sekaligus dampak kebijakan.","Tepat: hasil berulang perlu dilihat bersama struktur politik dan institusi.","Tidak tepat: ketidaksetaraan kompetisi tidak otomatis berarti tidak ada pemilih."],"strategi":["Pisahkan data jumlah kontestan dari penilaian demokratis.","Nilai dampak positif yang diklaim dan konsekuensi yang teramati.","Jangan melompat dari keterbatasan kompetisi ke klaim absolut."],"rujukan":{"label":"Sejarah penyelenggaraan pemilu - KPU","url":"https://kab-tobasamosir.kpu.go.id/page/read/sejarah-penyelenggaraan-pemilu-dan-pilkada","umum":false},"opsi":["Pengurangan kontestan mengubah struktur kompetisi pemilu.","Pemilu 1977 tetap diikuti puluhan partai seperti Pemilu 1999.","Stabilitas politik dapat dijadikan alasan kebijakan, tetapi konsekuensi terhadap pluralisme tetap perlu dinilai.","Dominasi satu kontestan berulang kali layak dianalisis dari konteks sistem politiknya.","Pembatasan jumlah kontestan otomatis membuktikan semua warga kehilangan hak pilih."],"kunci":["A","C","D"]},{"no":6,"tipe":"BS","judul":"Kontrol politik dan kebebasan warga","stimulus":"Selama Orde Baru pemilu diadakan secara periodik, sementara ruang kompetisi politik dan kritik publik mengalami pembatasan. Keberadaan sebuah prosedur politik tidak otomatis menggambarkan seluruh kualitas demokrasi.","tanya":"Nilailah setiap pernyataan.","analisis":["Benar: ukuran demokrasi tidak berhenti pada jadwal pemilihan.","Salah: prosedur dan pembatasan dapat hadir secara bersamaan.","Benar: ketentuan formal perlu dibandingkan dengan pelaksanaannya."],"strategi":["Bedakan indikator prosedural dan substansial demokrasi.","Periksa apakah stimulus membahas aturan atau kenyataan.","Waspadai penalaran \"jika A, pasti tidak B\" yang tidak didukung."],"rujukan":{"label":"Sejarah KPU dan perjalanan pemilu Indonesia","url":"https://kab-siak.kpu.go.id/page/read/sejarah-kpu","umum":false},"pernyataan":["Pemilu berkala harus dikaji bersama kondisi kebebasan politik dan persaingan.","Karena pemilu berlangsung, berarti tidak mungkin ada pembatasan aspirasi warga.","Penilaian atas masa Orde Baru perlu membedakan aturan resmi dan praktik politik."],"kunci":["B","S","B"],"label":"benar"},{"no":7,"tipe":"PG","judul":"Stabilitas politik dan partisipasi","stimulus":"Sebuah bacaan membandingkan dua pendapat mengenai Orde Baru. Pendapat pertama menekankan stabilitas dan kesinambungan program. Pendapat kedua menyoroti terbatasnya ruang kritik dan partisipasi politik masyarakat.","tanya":"Sikap historis paling tepat terhadap kedua pendapat tersebut adalah ...","analisis":["Keliru: ukuran kebijakan tidak tunggal.","Keliru: banyak perspektif adalah bahan untuk diuji.","Keliru: kritik atas pembatasan tidak menghapus seluruh capaian.","Tepat: evaluasi berdasar data dan sudut pandang beragam.","Keliru: sintesis historis memerlukan pengujian, bukan sekadar kompromi."],"strategi":["Identifikasi klaim dan ukuran keberhasilan masing-masing pendapat.","Cari opsi yang meminta pembuktian, bukan keberpihakan otomatis.","Bedakan kesimpulan bernuansa dari klaim serba baik atau serba buruk."],"rujukan":{"label":"Matriks dan karakter soal TKA Sejarah - Pusmendik","url":"https://pusmendik.kemdikbud.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"opsi":["mengambil pendapat pertama saja karena stabilitas merupakan satu-satunya ukuran sejarah.","menolak keduanya sebab penilaian kebijakan tidak dapat memakai banyak perspektif.","menganggap kritik selalu membuktikan seluruh pembangunan gagal.","menguji kedua pendapat dengan bukti tentang pencapaian, pembatasan, dan pengalaman berbagai kelompok.","menggabungkan dua pendapat tanpa memeriksa data yang dipakai."],"kunci":["D"]},{"no":8,"tipe":"MC","judul":"Pembangunan ekonomi dan pemerataan","stimulus":"Pemerintah Orde Baru menjalankan agenda stabilisasi ekonomi dan pembangunan. Sejumlah indikator infrastruktur serta kegiatan ekonomi berkembang, tetapi manfaatnya tidak selalu terbagi merata dan terdapat persoalan ketergantungan serta tata kelola.","tanya":"Pilih SEMUA langkah analisis yang sesuai dengan stimulus.","analisis":["Tepat: besarnya pertumbuhan tidak otomatis mengukur distribusi.","Tidak tepat: pengalaman wilayah beragam.","Tepat: indikator sosial dan geografis melengkapi angka makro.","Tidak tepat: statistik ekonomi harus dibaca bersama pengalaman masyarakat.","Tepat: sejarah kebijakan perlu memperhatikan akibat lintas waktu."],"strategi":["Periksa beda \"tumbuh\" dan \"merata\".","Gunakan sudut pandang waktu, wilayah, dan kelompok sosial.","Waspadai jawaban yang meniadakan indikator lain."],"rujukan":{"label":"Sejarah Bank Indonesia dan kebijakan ekonomi","url":"https://www.bi.go.id/id/tentang-bi/sejarah-bi/default.aspx","umum":false},"opsi":["Membedakan pertumbuhan ekonomi nasional dari pemerataan manfaat pembangunan.","Menyimpulkan semua desa mengalami kemajuan yang identik.","Mengkaji perubahan akses layanan dan kesenjangan antardaerah.","Mengabaikan kondisi sosial karena angka pertumbuhan adalah satu-satunya bukti.","Membandingkan capaian jangka pendek dengan dampak jangka panjang."],"kunci":["A","C","E"]},{"no":9,"tipe":"PG","judul":"Deregulasi perbankan 1988","stimulus":"Bank Indonesia mencatat Paket Kebijaksanaan 27 Oktober 1988 (Pakto 88) yang mempermudah perizinan pendirian bank baru. Kebijakan ini mendorong berkembangnya industri perbankan, sekaligus memperbesar kebutuhan pengawasan terhadap risiko sektor keuangan.","tanya":"Hubungan sebab-akibat yang paling tepat dari kebijakan tersebut adalah ...","analisis":["Tepat: ekspansi industri menuntut tata kelola dan pengawasan memadai.","Keliru: kemudahan akses tidak menghilangkan risiko keuangan.","Keliru: tahun 1988 mendahului krisis 1997.","Keliru: bertambahnya bank tidak menjamin kualitas penyaluran kredit.","Keliru: BI tetap menjadi bank sentral."],"strategi":["Cermati tahun kejadian untuk menghindari anakronisme.","Bedakan manfaat pembukaan pasar dari tantangan pengawasan.","Utamakan kesimpulan yang mempertimbangkan peluang serta risiko."],"rujukan":{"label":"Sejarah Bank Indonesia dan kebijakan ekonomi","url":"https://www.bi.go.id/id/tentang-bi/sejarah-bi/default.aspx","umum":false},"opsi":["kemudahan izin dapat memperluas kegiatan perbankan, namun perlu diimbangi pengawasan kesehatan bank.","pengurangan persyaratan pasti menghilangkan risiko perbankan.","Pakto 88 merupakan kebijakan yang dikeluarkan akibat krisis 1997.","pertumbuhan jumlah bank selalu berarti semua kredit pasti sehat.","Pakto 88 mengakhiri keberadaan Bank Indonesia."],"kunci":["A"]},{"no":10,"tipe":"BS","judul":"Perubahan sosial akibat pembangunan","stimulus":"Ilustrasi: pembangunan jalan memudahkan pengangkutan hasil kebun dari desa ke kota. Sebagian warga memperoleh peluang baru, tetapi pedagang kecil di jalur lama kehilangan pembeli. Perubahan sarana transportasi memengaruhi kelompok sosial secara tidak seragam.","tanya":"Tentukan BENAR atau SALAH.","analisis":["Benar: stimulus menampilkan kelompok dengan pengalaman berbeda.","Salah: stimulus justru memperlihatkan dampak yang tidak sama.","Benar: relasi ekonomi lokal berubah akibat akses transportasi baru."],"strategi":["Cari bukti perubahan sebelum dan sesudah.","Perhatikan pihak yang memperoleh manfaat maupun kehilangan peluang.","Hindari menggeneralisasi kondisi satu kelompok ke seluruh masyarakat."],"rujukan":{"label":"Matriks dan karakter soal TKA Sejarah - Pusmendik","url":"https://pusmendik.kemdikbud.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"pernyataan":["Pembangunan infrastruktur dapat menghadirkan manfaat dan kerugian berbeda bagi masyarakat.","Sebuah jalan baru pasti menguntungkan seluruh pelaku ekonomi dalam jumlah sama.","Dampak pembangunan sebaiknya dianalisis melalui perubahan mata pencaharian dan jaringan pasar."],"kunci":["B","S","B"],"label":"benar"},{"no":11,"tipe":"PG","judul":"Krisis Asia 1997 dan tekanan ekonomi","stimulus":"Krisis keuangan Asia pada 1997 memukul nilai tukar dan sektor perbankan Indonesia. Bank Indonesia melakukan langkah penanggulangan, termasuk perubahan sistem nilai tukar, penutupan bank bermasalah, dan restrukturisasi.","tanya":"Mengapa krisis ekonomi dapat memperluas desakan perubahan politik pada 1998?","analisis":["Keliru: perubahan harga dan usaha dapat memengaruhi masyarakat luas.","Keliru: dampak krisis meluas ke pekerjaan dan daya beli.","Tepat: hubungan ekonomi dan legitimasi politik dapat memperkuat tekanan reformasi.","Keliru: perubahan politik tidak berlangsung otomatis pada 1997.","Keliru: tanggapan warga terhadap krisis tidak selalu seragam."],"strategi":["Hubungkan gejala ekonomi dengan dampak sosial dan politik.","Bedakan pemicu, proses, dan hasil.","Singkirkan klaim otomatis yang tidak memiliki mekanisme sebab-akibat."],"rujukan":{"label":"Sejarah Bank Indonesia dan kebijakan ekonomi","url":"https://www.bi.go.id/id/tentang-bi/sejarah-bi/default.aspx","umum":false},"opsi":["Karena perubahan nilai tukar tidak pernah memengaruhi kehidupan warga.","Karena krisis hanya berdampak pada bank dan tidak berkaitan dengan ekonomi rumah tangga.","Karena tekanan ekonomi menambah ketidakpuasan publik ketika kepercayaan terhadap tata kelola pemerintahan melemah.","Karena pemerintah langsung meniadakan semua lembaga politik pada 1997.","Karena krisis memastikan setiap warga mendukung satu organisasi politik yang sama."],"kunci":["C"]},{"no":12,"tipe":"MC","judul":"Mahasiswa dan masyarakat sipil dalam Reformasi","stimulus":"Menjelang Mei 1998, protes mahasiswa, gerakan masyarakat sipil, dan kritik atas krisis ekonomi serta praktik pemerintahan menjadi semakin kuat. Berbagai kelompok menyuarakan tuntutan perubahan, sementara kekerasan dan kerusuhan menambah tragedi kemanusiaan.","tanya":"Pilih SEMUA penjelasan yang sejalan dengan konteks sejarah tersebut.","analisis":["Tepat: gerakan reformasi melibatkan unsur masyarakat yang beragam.","Tidak tepat: faktor penyebabnya berlapis.","Tepat: masalah ekonomi dan pemerintahan saling terkait.","Tidak tepat: kerusuhan menimbulkan korban dan pelanggaran serius.","Tepat: sejarah juga menyangkut pengalaman kelompok yang terdampak."],"strategi":["Identifikasi aktor kolektif, bukan hanya satu tokoh.","Pisahkan faktor ekonomi, politik, dan kemanusiaan.","Tolak klaim yang menghapus pengalaman korban dari analisis."],"rujukan":{"label":"Napak Reformasi Tragedi Mei 1998 - Komnas Perempuan","url":"https://komnasperempuan.go.id/instrumen-pemantauan-dan-monev-detail/napak-reformasi-tragedi-mei-1998","umum":false},"opsi":["Mahasiswa merupakan salah satu pelaku gerakan, bukan satu-satunya aktor.","Reformasi terjadi hanya karena satu pidato dari satu tokoh.","Krisis ekonomi dan tuntutan akuntabilitas dapat saling memperkuat.","Kerusuhan Mei 1998 tidak memiliki dimensi kemanusiaan sehingga tak perlu dipelajari.","Analisis Reformasi memerlukan perhatian pada aksi politik dan nasib korban kekerasan."],"kunci":["A","C","E"]},{"no":13,"tipe":"BS","judul":"Kerusuhan Mei 1998 dan ingatan sejarah","stimulus":"Komnas Perempuan dibentuk pada 1998 sebagai respons atas kekerasan terhadap perempuan dalam kerusuhan Mei. Pencarian fakta, dukungan bagi korban, dan upaya pencegahan menjadi bagian penting dari agenda reformasi hak asasi manusia.","tanya":"Nilailah tiga penafsiran berikut.","analisis":["Benar: respons kebijakan muncul setelah tuntutan perlindungan korban.","Salah: aspek kemanusiaan merupakan bagian penting sejarah reformasi.","Benar: akuntabilitas dan hak asasi berkaitan dengan kualitas demokrasi."],"strategi":["Kenali hubungan peristiwa kekerasan dan pembentukan lembaga.","Masukkan perspektif korban dalam penilaian sejarah.","Bedakan narasi politik elit dari pengalaman sosial masyarakat."],"rujukan":{"label":"Latar pembentukan Komnas Perempuan pasca-1998","url":"https://komnasperempuan.go.id/halaman/sejarah-komnas-perempuan","umum":false},"pernyataan":["Pembentukan lembaga perlindungan dapat menjadi respons kelembagaan terhadap kekerasan masa lalu.","Peristiwa Mei 1998 sebaiknya dijelaskan tanpa menyebut pengalaman korban karena tidak berkaitan dengan sejarah politik.","Pengungkapan fakta dan perlindungan korban relevan dalam kajian transisi demokrasi."],"kunci":["B","S","B"],"label":"benar"},{"no":14,"tipe":"PG","judul":"21 Mei 1998 sebagai titik balik","stimulus":"Pada 21 Mei 1998, Presiden Soeharto menyatakan berhenti dari jabatan setelah rangkaian krisis serta tekanan politik dan sosial. Masa Reformasi dimulai, tetapi perbaikan institusi demokrasi memerlukan keputusan dan proses lanjutan.","tanya":"Makna historis yang paling akurat dari 21 Mei 1998 adalah ...","analisis":["Keliru: agenda penegakan hukum membutuhkan waktu panjang.","Keliru: dampak krisis masih berlangsung.","Keliru: reformasi tidak mengganti seluruh sistem sekaligus.","Tepat: pergantian presiden merupakan titik balik, bukan akhir semua proses.","Keliru: reformasi justru membuka ruang partisipasi warga."],"strategi":["Bedakan peristiwa titik balik dan proses jangka panjang.","Perhatikan kata \"mulai\" serta \"lanjutan\" dalam stimulus.","Hindari jawaban yang menyatakan semua masalah langsung selesai."],"rujukan":{"label":"Napak Reformasi Tragedi Mei 1998 - Komnas Perempuan","url":"https://komnasperempuan.go.id/instrumen-pemantauan-dan-monev-detail/napak-reformasi-tragedi-mei-1998","umum":false},"opsi":["selesainya seluruh agenda pemberantasan korupsi dan penegakan HAM dalam satu hari.","berakhirnya seketika semua persoalan ekonomi di Indonesia.","penghapusan seluruh undang-undang dan lembaga negara sejak masa sebelumnya.","titik balik pergantian kepemimpinan yang membuka proses reformasi kelembagaan berikutnya.","berakhirnya kebutuhan partisipasi warga dalam kehidupan demokrasi."],"kunci":["D"]},{"no":15,"tipe":"MC","judul":"Pemilu 1999 dan kompetisi multipartai","stimulus":"Pemilu 1999 berlangsung setelah berakhirnya Orde Baru dengan partisipasi banyak partai politik. Dibanding pemilu 1977–1997 yang memiliki tiga kontestan, perubahan ini memperlihatkan perluasan pilihan politik, meski tantangan tata kelola demokrasi tetap ada.","tanya":"Pilih SEMUA simpulan yang sesuai dengan perbandingan tersebut.","analisis":["Tepat: perubahan kepesertaan merupakan fakta perubahan sistem pemilu.","Tidak tepat: pemilu Reformasi menghadirkan lebih banyak peserta.","Tepat: pilihan politik lebih beragam.","Tepat: mutu demokrasi juga memerlukan akuntabilitas dan penegakan aturan.","Tidak tepat: pemilihan presiden langsung baru diterapkan pada 2004."],"strategi":["Bandingkan variabel yang sama pada dua periode.","Jangan samakan kompetisi multipartai dengan demokrasi yang sempurna.","Periksa kronologi pemilihan presiden secara langsung."],"rujukan":{"label":"Sejarah KPU dan perjalanan pemilu Indonesia","url":"https://kab-siak.kpu.go.id/page/read/sejarah-kpu","umum":false},"opsi":["Jumlah peserta pemilu mencerminkan perubahan aturan kompetisi politik.","Pemilu 1999 diikuti hanya tiga kontestan yang sama persis seperti pemilu 1997.","Bertambahnya pilihan partai merupakan salah satu indikator perubahan ruang partisipasi.","Meningkatnya pilihan politik tidak otomatis menjamin semua persoalan demokrasi selesai.","Pemilu 1999 membuktikan presiden sudah dipilih langsung oleh rakyat pada saat itu."],"kunci":["A","C","D"]},{"no":16,"tipe":"BS","judul":"Perubahan UUD 1945 pada 1999–2002","stimulus":"Perubahan UUD 1945 dilaksanakan empat tahap pada 1999, 2000, 2001, dan 2002. Perubahan tersebut memengaruhi relasi lembaga negara, pembatasan kekuasaan, hak asasi manusia, dan mekanisme demokrasi.","tanya":"Tentukan BENAR atau SALAH.","analisis":["Benar: perubahan berlangsung pada empat tahun sidang.","Salah: bentuk Negara Kesatuan Republik Indonesia dipertahankan.","Benar: pembatasan kekuasaan dan keseimbangan lembaga mendapat perhatian."],"strategi":["Ingat rentang tahun 1999–2002 sebagai proses.","Bedakan perubahan aturan kelembagaan dan prinsip dasar yang dipertahankan.","Uji setiap klaim terhadap isi perubahan konstitusi."],"rujukan":{"label":"Naskah komprehensif perubahan UUD 1945 - MK","url":"https://simpus.mkri.id/opac/detail/8978","umum":false},"pernyataan":["Perubahan konstitusi merupakan proses bertahap, bukan satu keputusan tunggal.","Amandemen tersebut menghapus bentuk negara kesatuan Indonesia.","Penataan hubungan antarlembaga negara menjadi salah satu sasaran perubahan konstitusi."],"kunci":["B","S","B"],"label":"benar"},{"no":17,"tipe":"PG","judul":"Pemilihan presiden langsung 2004","stimulus":"Sebelum 2004, pemilihan presiden dilakukan melalui MPR. Pada Pemilu 2004, rakyat Indonesia untuk pertama kalinya menggunakan hak pilih secara langsung untuk memilih pasangan presiden dan wakil presiden.","tanya":"Perubahan yang paling jelas ditunjukkan oleh peristiwa tersebut adalah ...","analisis":["Keliru: pemilu legislatif tetap ada.","Tepat: mekanisme legitimasi pemilihan presiden mengalami perubahan.","Keliru: partai politik masih memiliki peran pencalonan.","Keliru: sistem Reformasi tidak kembali ke pola tiga kontestan Orde Baru.","Keliru: masa jabatan justru dibatasi dalam konstitusi."],"strategi":["Cari apa yang berubah dalam mekanisme, bukan seluruh sistem negara.","Bedakan pemilu legislatif dan pemilu presiden.","Identifikasi lembaga atau pemilih yang menentukan hasil akhir."],"rujukan":{"label":"Sejarah penyelenggaraan pemilu - KPU","url":"https://kab-tobasamosir.kpu.go.id/page/read/sejarah-penyelenggaraan-pemilu-dan-pilkada","umum":false},"opsi":["penghapusan kebutuhan pemilihan anggota legislatif.","pemindahan mekanisme pemilihan presiden dari MPR kepada pemilih secara langsung.","pengakhiran seluruh peran partai politik dalam pencalonan.","pengembalian sistem pemilu tiga kontestan seperti Orde Baru.","penghapusan masa jabatan dan ketentuan konstitusional kepresidenan."],"kunci":["B"]},{"no":18,"tipe":"MC","judul":"Otonomi daerah dan tata kelola","stimulus":"Undang-Undang Nomor 22 Tahun 1999 menjadi tonggak desentralisasi pemerintahan setelah Reformasi. Sebagian kewenangan didekatkan ke daerah untuk memperkuat respons terhadap kebutuhan warga, sementara kebutuhan koordinasi dan pengawasan tetap penting.","tanya":"Pilih SEMUA evaluasi yang relevan terhadap kebijakan otonomi daerah.","analisis":["Tepat: kedekatan pengambilan keputusan berpotensi meningkatkan respons.","Tidak tepat: negara tetap memiliki koordinasi dan fungsi nasional.","Tepat: kewenangan perlu ditopang sumber daya serta akuntabilitas.","Tepat: pelayanan warga adalah indikator yang dapat diuji.","Tidak tepat: kemampuan daerah dan hasil kebijakan beragam."],"strategi":["Bedakan desentralisasi dari pemisahan negara.","Nilai kebijakan melalui tujuan, syarat keberhasilan, dan dampak.","Hindari klaim bahwa otonomi langsung menghasilkan keseragaman."],"rujukan":{"label":"UU Nomor 22 Tahun 1999 tentang Pemerintahan Daerah","url":"https://peraturan.bpk.go.id/Details/45329/uu-no-22-tahun-1999","umum":false},"opsi":["Daerah dapat memiliki ruang lebih luas menyesuaikan layanan dengan kebutuhan lokal.","Otonomi berarti pemerintah pusat tidak lagi memiliki fungsi apa pun.","Pemindahan kewenangan membutuhkan kapasitas aparat dan pengawasan anggaran.","Keberhasilan otonomi daerah dapat dinilai dari mutu pelayanan publik.","Desentralisasi selalu membuat kualitas layanan tiap daerah menjadi sama dalam satu hari."],"kunci":["A","C","D"]},{"no":19,"tipe":"BS","judul":"Bank sentral independen dan reformasi ekonomi","stimulus":"Undang-Undang Nomor 23 Tahun 1999 menjadi tonggak baru bagi kedudukan Bank Indonesia sebagai bank sentral independen dengan fokus kestabilan nilai rupiah. Reformasi kelembagaan ini muncul sesudah pengalaman krisis keuangan 1997–1998.","tanya":"Nilailah setiap pernyataan berikut.","analisis":["Benar: pengalaman krisis menjadi konteks penting bagi pembaruan kebijakan.","Salah: penguatan kelembagaan tidak menghapus kemungkinan krisis.","Benar: Reformasi mencakup lebih dari pergantian kepemimpinan politik."],"strategi":["Hubungkan urutan krisis dan respons kelembagaan.","Jangan menafsirkan reformasi sebagai jaminan hasil sempurna.","Amati kesinambungan dan perubahan fungsi lembaga."],"rujukan":{"label":"Sejarah Bank Indonesia dan kebijakan ekonomi","url":"https://www.bi.go.id/id/tentang-bi/sejarah-bi/default.aspx","umum":false},"pernyataan":["Krisis dapat mendorong evaluasi dan pembaruan lembaga ekonomi.","Independensi Bank Indonesia pada 1999 berarti seluruh risiko ekonomi pasti hilang.","Perubahan aturan bank sentral menunjukkan dampak Reformasi juga berlangsung di bidang ekonomi."],"kunci":["B","S","B"],"label":"benar"},{"no":20,"tipe":"PG","judul":"Menilai warisan Reformasi secara historis","stimulus":"Dua laporan mengenai Indonesia pasca-1998 berbeda penekanan. Laporan A menyebut meningkatnya pilihan politik melalui pemilu, sedangkan Laporan B menyoroti bahwa korupsi, kesenjangan, dan persoalan penegakan hukum tetap menjadi tantangan. Keduanya membahas aspek yang tidak selalu bergerak serempak.","tanya":"Kesimpulan yang paling bertanggung jawab secara historis adalah ...","analisis":["Keliru: persoalan tersisa tidak meniadakan perubahan kelembagaan yang terjadi.","Keliru: prosedur demokrasi bukan satu-satunya ukuran keberhasilan.","Keliru: kritik dan laporan capaian dapat membahas dimensi berbeda.","Keliru: dua keadaan berbeda bisa berlangsung bersamaan.","Tepat: analisis sejarah mengenali perubahan, keberlanjutan, dan ragam indikator."],"strategi":["Bedakan indikator capaian politik dari masalah sosial-ekonomi.","Uji kedua klaim dengan ukuran dan bukti relevan.","Pilih simpulan yang menghindari penilaian hitam-putih."],"rujukan":{"label":"Matriks dan karakter soal TKA Sejarah - Pusmendik","url":"https://pusmendik.kemdikbud.go.id/tka/tka/view/mata-pelajaran-pilihan/sma/sejarah","umum":true},"opsi":["Reformasi pasti gagal total karena sebagian masalah belum selesai.","Reformasi telah menyelesaikan seluruh masalah hanya karena pemilu lebih terbuka.","Laporan yang membahas capaian harus ditolak karena berbeda dari laporan kritik.","Kedua laporan tak mungkin benar pada waktu yang sama.","Perubahan demokrasi dapat berlangsung bersama keberlanjutan persoalan; keduanya perlu diuji dengan bukti dan indikator yang jelas."],"kunci":["E"]}]};
